export interface BusinessProfile {
  name: string;
  industry: string | null;
  category: string | null;
  city: string | null;
  rating: number | null;
  reviewCount: number | null;
  website: string | null;
  description: string | null;
}

// Governance layer (Phases 1–5): the fired-leak taxonomy result threaded through
// every deliverable so generation is grounded ONLY in leaks that actually fired,
// graded deterministically, with a bounded allowed-number set for the stat guard.
export interface LeakContext {
  /** In-scope fired leaks, ranked desc (reportLeaks). */
  report: FiredLeak[];
  /** Cold-audit top-3 (selectColdAudit). */
  coldAudit: FiredLeak[];
  /** Out-of-scope fired flags → "Also worth knowing" only. */
  outOfScope: FiredLeak[];
  /** Deterministic 9-axis grades (gradeAreas, decision 2). */
  grades: Record<ScorecardArea, number>;
  /** Rendered "write ONLY from this" leak block (leakInputsToPromptBlock). */
  promptBlock: string;
  /** Every number the copy is permitted to print (allowedNumbersFor). */
  allowedNumbers: number[];
  /** Structured per-fired-leak inputs (buildLeakInputs) — drives deterministic
   *  stamping of the leak analysis (identity, stats, math, kickoff line). */
  inputs: LeakInput[];
  /** Cold-audit headline leak (Part H1): the #1 ranked leak shown, plus its
   *  pre-computed benchmark-mode monthly figure (null when it has no math). */
  headline?: { leakName: string; benchmarkFrame: string | null } | null;
}

export interface GenerationContext {
  business: BusinessProfile;
  intel: AuditIntelligence;
  websiteText: string;
  /** Present once the leak-detection pipeline has run for this business. */
  leaks?: LeakContext;
  /** Services the client wants more of, from the intake form. COPY EMPHASIS ONLY:
   *  shapes wording in landing/email/SMS/roadmap copy, never leak facts/math. */
  servicesFocus?: string;
  /** TRUE when ANY intake field was provided for this business. When false the
   *  pack is generated on the pure pre-intake TESTING path and every document
   *  cover carries an "INTERNAL TEST — generated without client intake" marker. */
  intakePresent?: boolean;
  /** Named scheduler the client already uses (intake bookingMethod = BOOKING_TOOL).
   *  Reframes the booking system as CONNECTING + OPTIMIZING this tool, never adding
   *  booking they lack. COPY EMPHASIS ONLY. */
  bookingToolName?: string;
  /** Who manages the Google Business listing (intake): "SELF" | "NOT_SELF" |
   *  "SOMEONE_ELSE" | "NOT_SURE". FRAMING ONLY for the review engine — never
   *  suppresses a review leak or changes any fact/number. */
  gbpManagement?: string;
  /** Build features the client asked to prioritize (intake checkbox), already
   *  mapped to human labels. ORDERING + copy emphasis ONLY for the Blueprint. */
  buildPriorities?: string[];
  /** The client's intake answers, used for ONE thing here: deciding which of the
   *  fourteen catalogue workflows are in THIS client's build (resolveWorkflow).
   *  Absent is a safe, meaningful state — with nothing on file every workflow
   *  stays in, which is the catalogue's own rule and the honest default for a
   *  pre-intake or pre-sale document. */
  intake?: ClientIntake | null;
  /** The operator's explicit per-workflow decisions, exactly as stored in
   *  Business.workflowToggles. An absent key means "no opinion, use the rule". */
  workflowToggles?: WorkflowToggles | null;
}

// Maps PsiResult → the compact shape we ship in the deliverable JSON.
function shapePsi(
  r: { performanceScore: number | null; metrics: { lcpSeconds: number | null; cls: number | null; inpMs: number | null } } | null
): { score: number | null; lcpSeconds: number | null; cls: number | null; inpMs: number | null } | null {
  if (!r) return null;
  return {
    score: r.performanceScore,
    lcpSeconds: r.metrics.lcpSeconds,
    cls: r.metrics.cls,
    inpMs: r.metrics.inpMs,
  };
}

const STYLE_RULES = `You are a senior client-acquisition strategist whose audits command premium fees. You have diagnosed hundreds of local service businesses and you know exactly where they leak revenue. You write like an expensive operator showing the client the receipts — not a marketer, blogger, or AI. The reader is a SKEPTICAL business OWNER who has seen generic "marketing audits" and hates them. The only things that earn their money: specificity they couldn't have written themselves, leaks quantified in dollars, and conclusions they can't argue with.

BUSINESS MODEL (everything you write must fit this):
- The client ALREADY gets enquiries — however those enquiries reach them (their listing, their site, word of mouth, repeat customers). Where the enquiries come from is NOT your subject and NOT something this engagement touches: we do not run, buy, manage, or advise on ads, SEO, or any other traffic source. The problem you solve is CONVERSION: they lose most enquiries before those become customers — slow response, no qualification, no follow-up, no-shows, weak on-page conversion. The promise: "You are already getting enquiries. We make more of them turn into customers." Never write a sentence that assumes the client runs paid ads or that implies we would touch their ad spend.
- The offer has TWO parts: (1) a one-time DONE-FOR-YOU setup where WE implement the fixes — the client builds nothing; (2) a monthly QUALIFICATION RETAINER powered by ${PRODUCT_NAME} — the AI lead-qualification + routing engine that runs continuously. That recurring engine is ${PRODUCT_NAME}; name it.
- The reader has NO team — solo owner or a couple of staff. Never assign work to a "Marketing Team", "Web Dev Team", "Sales Team", "CRM Specialist", or "IT Team".

${SYSTEM_FRAMING}

NON-NEGOTIABLE LAWS:
1. GROUND EVERYTHING IN REAL DATA. Every quantitative claim traces to a provided input. Never invent a number, competitor, metric, or finding. If data is missing, cut the claim or mark it a stated assumption.
2. CONVERSION-ONLY SCOPE. Diagnose/fix ONLY the lead→customer path: speed-to-lead, lead qualification, follow-up/nurture, booking, no-show recovery, on-page conversion/trust (hero, CTA, form, mobile speed). Do NOT prescribe lead generation — no paid ads, SEO, social growth, content marketing, "local authority", events, or referral programs. Only allowed exception: review-REQUEST automation after a job, framed as a post-sale trust asset, never a ranking campaign. NOT A REDESIGN: any on-page fix (hero, CTA, form, page) is framed as the visible surface of a system fix — the acquisition system is the deliverable, never a cosmetic "redesign", "new look", or "refresh". Never imply the client is buying a prettier website.
3. DONE-FOR-YOU FRAMING. WE implement everything. Frame fixes as "here's what we deploy for you," not "here's what you should build." Owner is "us" for everything implemented; "you" ONLY for genuine human-judgment steps (showing up to the consult, answering a qualified lead, approving copy). Never assign tasks to roles a small local business does not have.
4. POSITION THE RETAINER. The lead-qualification + routing layer IS ${PRODUCT_NAME}. Name it. Make clear it RUNS CONTINUOUSLY and is what the monthly retainer pays for — distinct from the one-time setup.
5. USE ONLY THE PROVIDED FIGURES. Every dollar amount, percentage, and multiplier you print MUST come verbatim from the leak-analysis block supplied to you (its pre-computed math and allowed numbers). NEVER invent, derive, or estimate your own figure. If a leak has no supplied dollar figure, describe the leak qualitatively and anchor it to the cost of an enquiry ("this is leaking a share of what it already costs you to get an enquiry") — do NOT attach a fabricated revenue number. Pre-intake, make ZERO claims about the client's revenue; frame impact against the industry cost-per-lead figure supplied in the block only, and never assert that the client buys ads. When a figure IS supplied, show it with the labeled math beside it.
6. DEFENSIBLE SCORES ONLY. Every score shows its rubric and the specific real evidence behind it. Scores must MATCH the narrative — never score 70/100 while describing it as deficient.
7. ZERO TAUTOLOGIES. Ban sentences true of every business ("CTAs guide users to act", "trust builds credibility", "following up increases conversion", "X is crucial for conversion"). Replace with what's true of THIS business using its real data and a named competitor's real numbers.
8. LEAD WITH THE GUT-PUNCH. Open with the most damning, dollar-quantified CONVERSION finding — never a compliment ("strong reputation, 5-star rating").
9. FRAME AGAINST REAL COMPETITORS where data allows — "them vs you" with the actual scraped competitors and their actual numbers.
10. VOICE. Confident on the DIAGNOSIS (it's measured data — state it plainly), honest on projected OUTCOMES (never guarantee results). Kill hedge-soup — don't pile "may/could/potentially/likely/designed to" onto observed facts. Authoritative, concrete, short sentences, no hype, no emoji.
11. NEVER PRINT THE SCAFFOLD. The field hints and analysis dimensions in this prompt are instructions for what to ANALYZE — they must NEVER appear verbatim in your output. Strings like "headline clarity / subheadline strength / CTA visibility / above-the-fold trust / local relevance / intent match" or "urgency & specificity — diagnose the intent mismatch" are scaffolding. Convert every checklist into actual prose findings about THIS business. If a slash-delimited list of analysis dimensions ever appears in a value you emit, that is a bug — replace it with real findings written as sentences.
12. RECONCILE EVERY DOLLAR FIGURE. All dollar figures must be internally consistent across the whole pack. Compute each per-leak figure FIRST in the leak analysis, then make any executive-summary total equal the sum (or a clearly-stated subset) of those itemized leaks. The same leak shows the same number everywhere. Never let one section contradict another (e.g. the exec summary must not state a larger range for a leak than its own itemized analysis). State the rolled-up total explicitly when you give one.
13. LABEL EVERY ASSUMPTION, INCLUDING VOLUME. Lead volume, visitor counts, and consult counts are usually NOT in the scraped data. Never present an invented volume as a derived fact (do not write "20 leads/mo based on online inquiries" when nothing was measured). If a volume is not from real data, label it an assumption every place it is used: "Assuming ~20 leads/mo — replace with your actual number to make this exact." Same rule for avg customer value (see below).
14. BANNED VOCABULARY, AND NO UNLABELLED DOLLAR FIGURE. The words "guaranteed", "guarantee", "skyrocket", "secret", and "hack" are forbidden anywhere in your output — including inside an FAQ answer written in the CLIENT's own voice, where they become a fabricated promise made on the client's behalf. Never write a promise in ALL CAPS. Separately: never write a dollar amount that is not either (a) supplied verbatim in the leak-analysis block with its math beside it, or (b) labelled in the SAME sentence as an assumption. That bans illustrative magnitudes too — do not write "a tire-kicker or a $20k job", because no $20k job was measured. Reach for a non-numeric contrast instead ("a tire-kicker or your biggest job of the year"). Each of these is a hard validator failure that blocks the whole pack from being saved or exported, so one slip costs a full regeneration.

CALCULATION RULES (use ONLY supplied figures — never fabricate):
- Every percentage, multiplier, and dollar amount MUST come from the leak-analysis block supplied to you. Do NOT bring in remembered industry rules of thumb (conversion-drop percentages, response-time multipliers, no-show rates, etc.). If the block does not supply a number for a leak, keep the finding qualitative.
- Do NOT invent an avg customer value or a monthly lead volume. Pre-intake, no such figures are known — do not present benchmarks or assumed volumes as facts, and make no claim about the client's revenue. Anchor impact to what the block provides (the industry cost-per-lead figure), which is the only pre-intake dollar frame permitted — and do not assume the client is paying for ads to get those leads.
- When the block DOES supply a dollar figure or range for a leak, print it exactly as given, with the supplied inputs shown beside it. Never state a dollar figure without the supplied math beside it. RECONCILE: the same leak shows the same supplied number everywhere; any exec-summary total must equal the sum of the per-leak supplied figures (Law 12).

OUTPUT: Return ONLY valid JSON matching the requested shape exactly. No commentary outside the JSON.`;

// Shared 4-section framing every deliverable must carry. The "Actual
// Deliverable" is the file's existing content; framing wraps it with an
// Overview (what + why for THIS business), an Implementation Guide (how to
// deploy), and Expected Impact (the realistic outcome). Keep it specific,
// non-generic, and free of platform/agency self-reference.
function framingInstruction(deliverableName: string): string {
  return `Also produce a "framing" object that positions this deliverable for the business owner reading it:
- overview: 2-4 sentences on what ${deliverableName} is and why it matters for THIS specific business and city. No generic boilerplate.
- implementationGuide: 4-7 ordered, plain-English steps the owner or their VA follows to put this live (tools, where to paste, what to switch on). Practical, not theoretical.
- expectedImpact: 2-3 sentences on the realistic business outcome once this is running (more booked jobs, better lead quality, fewer no-shows, higher close rate). Honest — no inflated numbers.`;
}

const FRAMING_SCHEMA = `"framing": {"overview": "...", "implementationGuide": ["..."], "expectedImpact": "..."},`;

function profileBlock(b: BusinessProfile, websiteText: string): string {
  const lines = [
    `Name: ${b.name}`,
    `Industry: ${b.industry ?? "local business"}`,
    `Category: ${b.category ?? b.industry ?? "local business"}`,
    `City: ${b.city ?? "their local area"}`,
    `Rating: ${b.rating ? `${b.rating}/5 from ${b.reviewCount ?? 0} reviews` : "not available"}`,
    `Website: ${b.website ?? "none on record"}`,
    `Description: ${b.description ?? "none provided"}`,
  ];
  let block = `BUSINESS PROFILE\n${lines.join("\n")}`;
  if (websiteText) {
    block += `\n\nLIVE WEBSITE COPY (reference their ACTUAL services, offers, tone; use to spot weak CTAs / missing trust signals / outdated positioning):\n"""\n${websiteText}\n"""`;
  } else {
    block += `\n\nNo readable website copy was available — infer likely services from the niche and improve the weak positioning typical of this business type.`;
  }
  return block;
}

export function contextHeader(ctx: GenerationContext): string {
  const parts = [
    profileBlock(ctx.business, ctx.websiteText),
    "",
    "AUDIT INTELLIGENCE BRIEFING (heuristically extracted — treat as ground truth where marked real, and respect the labelled assumptions):",
    intelligenceToPromptBlock(ctx.intel),
  ];
  if (ctx.leaks) {
    parts.push("", "════════ GOVERNED LEAK SET ════════", ctx.leaks.promptBlock);
    const routing = routingAppendix(ctx.leaks.report);
    if (routing) parts.push(routing);
    if (ctx.leaks.outOfScope.length) {
      const names = ctx.leaks.outOfScope.map((f) => f.leak.name).join(" · ");
      parts.push(
        `OUT OF SCOPE (mention ONLY under an "Also worth knowing" aside — observed data + framing, NEVER as a core leak, NEVER with a dollar figure, and NEVER with a fix or recommendation attached): ${names}`
      );
    }
  }
  if (ctx.servicesFocus) {
    parts.push(
      "",
      `COPY EMPHASIS — SERVICES THEY WANT MORE OF (from the client's intake form): "${ctx.servicesFocus}". Where it reads naturally, let landing-page headlines/CTAs and the email/SMS examples speak to these services, and use them as concrete examples in the blueprint/roadmap. HARD BOUNDARY — WORDING ONLY: this changes phrasing, never facts. It must NOT add, remove, or reweight any leak, and must NOT change any score, tier, dollar figure, statistic, or calculation — the governed leak set above is the sole authority on what is wrong and what it costs. Never invent a fact, number, offer, or claim about these services; only the leaks and figures already supplied may be stated.`
    );
  }
  if (ctx.bookingToolName) {
    parts.push(
      "",
      `BOOKING — TOOL ALREADY IN PLACE (from intake): the client already takes bookings through ${ctx.bookingToolName}. Frame the booking system as CONNECTING and OPTIMIZING ${ctx.bookingToolName} into the lead flow (wiring it to instant response, reminders, and no-show recovery) — NEVER as adding online booking they lack, and NEVER say "you have no booking". They have booking; the work is integration and conversion. WORDING ONLY: do not add/remove/reweight any leak or change any figure.`
    );
  }
  if (ctx.gbpManagement) {
    const gbpLine =
      ctx.gbpManagement === "SELF"
        ? "The client manages their own Google Business listing, so review-request automation is framed as YOU approving/sending the requests — you own the listing."
        : ctx.gbpManagement === "SOMEONE_ELSE"
        ? "Someone else manages the client's Google Business listing, so frame review-request automation as us COORDINATING with whoever manages their listing to connect it."
        : ctx.gbpManagement === "NOT_SELF"
        ? "The client does not manage their own Google Business listing, so frame review-request automation as us confirming who controls the listing and coordinating access to connect it."
        : "It's not yet confirmed who manages the client's Google Business listing — note that ownership of the listing is verified at kickoff before the review engine is connected.";
    parts.push(
      "",
      `GBP MANAGEMENT — REVIEW-ENGINE FRAMING ONLY (from intake): ${gbpLine} HARD BOUNDARY: this changes ONLY how the review-request work is framed — it must NOT suppress, add, or reweight any review leak or change any score/figure. Review findings come from observed review data regardless of who manages the listing.`
    );
  }
  if (ctx.buildPriorities?.length) {
    parts.push(
      "",
      `BUILD PRIORITIES — ORDERING & EMPHASIS ONLY (from the client's intake checkbox): the client asked to prioritize these systems first, in this order — ${ctx.buildPriorities.join(
        " · "
      )}. In the Blueprint and the roadmap, lead with and give more detail to the items that match these priorities (wire the checked doors first). HARD BOUNDARY — ORDERING/WORDING ONLY: this changes sequence and emphasis, never facts. It must NOT add, remove, or reweight any leak, and must NOT change any score, tier, dollar figure, or calculation. The governed leak set above remains the sole authority on what is wrong and what it costs.`
    );
  }
  return parts.join("\n");
}

// DELIVERABLE_ROUTING (Phases 1–5): each fired leak carries a fixed fix identity —
// which asset builds it, which roadmap phase it ships in, which pack items it
// consumes. Surfacing it deterministically lets the roadmap, blueprint, and asset
// pack place every fired leak into the SAME phase/asset across deliverables,
// ordered by ranking score (highest-impact first), instead of the model guessing.
const ROADMAP_PHASE_LABELS: Record<1 | 2 | 3 | 4, string> = {
  1: "Foundation",
  2: "Infrastructure",
  3: "Launch",
  4: "Optimization",
};
function routingAppendix(report: FiredLeak[]): string {
  const rows = report
    .filter((f) => f.leak.ghlFix)
    .map((f) => {
      const fix = f.leak.ghlFix!;
      const items = fix.assetPackItems?.length ? ` — pack items: ${fix.assetPackItems.join(", ")}` : "";
      return `- ${f.leak.name} → build "${fix.assetName}" in Phase ${fix.roadmapPhase} (${ROADMAP_PHASE_LABELS[fix.roadmapPhase]})${items}`;
    });
  if (!rows.length) return "";
  return [
    "FIX ROUTING (deterministic — place each fired leak's fix in exactly this phase/asset, ordered highest-impact first; do not invent other phases or assets):",
    ...rows,
  ].join("\n");
}

// ══════════════════════════════════════════════════════════════════════════════
// THE BUILD, RENDERED INTO PROMPTS AND STAMPED INTO OUTPUT
// ══════════════════════════════════════════════════════════════════════════════
//
// Everything in this block exists so that no model call ever has to be TOLD what
// the build is in prose that somebody retyped. Each constant below is either
// (a) read straight out of src/lib/workflow-catalogue.ts, or (b) a fixed string
// we own — a price, a scope sentence, a schedule. The model writes the parts that
// are genuinely about THIS business; the parts that are the same in every build
// are stamped, so they cannot drift, be paraphrased, or quietly go missing.

/** The one-time build. Marker BEFORE the figure — the money format is a rule. */
const ONE_TIME_INVESTMENT = "CAD $6,500";
/** The monthly service. */
const MONTHLY_INVESTMENT = "CAD $1,000";

/** In the build and not a workflow. Stamped, so the Blueprint always lists the
 *  same things the operator actually stands up inside the sub-account. */
const BUILD_ALSO_INCLUDED: string[] = [
  "A booking page we build and brand inside your GoHighLevel sub-account — the one page we build.",
  "A booking calendar wired to your real availability, so a time offered is a time you can keep.",
  "A lead-capture form that feeds the same pipeline as your calls, texts and chats.",
  `Your six-stage pipeline — ${PIPELINE_STAGES.join(" → ")} — so every enquiry sits in exactly one place.`,
  "A dedicated tracked phone number that forwards to the phone you already answer.",
  "Custom values and custom fields, so a change to your booking link or hours updates every message at once.",
  "A reporting dashboard showing what came in, what got booked, and what got won.",
];

/** Said out loud in the Blueprint. An unstated boundary becomes an expectation,
 *  and the two most expensive assumptions a client can make are "you'll fix my
 *  website" and "you'll get me more leads". */
const BUILD_NOT_INCLUDED: string[] = [
  "We do not build, rebuild or host your website. Anything we find on your own site is written up as advice you can hand to whoever looks after it.",
  // The wording here is deliberate and it is not a style choice: the pack
  // validator hard-fails on the phrase "search ranking" wherever it appears,
  // because that phrase belongs to work we do not sell. Saying what we do not do
  // has to be said in words that are themselves in scope.
  "We do not run or advise on advertising, on getting found in search, or on growing a following. This engagement is about converting the enquiries you already get.",
  "Lead qualification is not part of the one-time build — it runs every day and is tuned every month, so it sits in the monthly service.",
];

// ── GoHighLevel merge fields ─────────────────────────────────────────────────
// The operator pastes these strings into a real workflow. A merge field that
// does not exist renders as empty text in front of a customer — "Hi ," at the top
// of the first message the business ever sends them. So the model is given the
// list it may use and told plainly that inventing one is not allowed.
const GHL_MERGE_FIELDS: { field: string; meaning: string }[] = [
  { field: "{{contact.first_name}}", meaning: "the customer's first name" },
  { field: "{{contact.name}}", meaning: "the customer's full name" },
  { field: "{{contact.phone}}", meaning: "the customer's phone number" },
  { field: "{{location.name}}", meaning: "the business name" },
  { field: "{{location.phone}}", meaning: "the business's tracked number" },
  { field: "{{user.first_name}}", meaning: "whoever the lead is assigned to" },
  { field: "{{appointment.start_time}}", meaning: "the booked date and time" },
  { field: "{{custom_values.booking_link}}", meaning: "the booking page link" },
  { field: "{{custom_values.review_link}}", meaning: "the Google review link" },
  { field: "{{custom_values.payment_link}}", meaning: "the payment link" },
];

function mergeFieldBlock(): string {
  return [
    "GOHIGHLEVEL MERGE FIELDS — use ONLY these, exactly as written, and list the ones you used in `mergeFields`:",
    ...GHL_MERGE_FIELDS.map((m) => `  ${m.field} — ${m.meaning}`),
    "NEVER invent a merge field and never write a placeholder like [Business] or [name] where a merge field exists: an unknown field renders as empty text in front of a customer. Where no merge field fits, write the words out.",
  ].join("\n");
}

// ── The 60-day nurture sequence ──────────────────────────────────────────────
// This is workflow 8 in the catalogue — "Lead Nurture — No Booking" — and it is
// ONE workflow, not two. File 3 writes its seven emails and file 4 writes its six
// texts, but they interleave on a single 60-day canvas and the sequence ends by
// moving the deal to Lost.
//
// THE SCHEDULE IS DEFINED HERE, NOT BY THE MODEL, and the reason is mechanical:
// the operator is pasting thirteen strings into thirteen boxes. If the numbering
// is model-authored it changes between regenerations, two documents disagree
// about which message is "the fourth one", and he has to reconstruct the timing
// by reading the copy. Stamped, it is a mechanical paste.
export interface NurtureStep {
  /** Position in the full 13-step workflow. */
  step: number;
  channel: "Email" | "Text";
  /** Number within its own half — Email 1–7, Text 1–6. */
  index: number;
  /** Days after the lead enters the sequence. */
  day: number;
  purpose: string;
}

export const NURTURE_SEQUENCE: readonly NurtureStep[] = [
  { step: 1, channel: "Text", index: 1, day: 1, purpose: "Short nudge — pick the conversation back up and offer a time" },
  { step: 2, channel: "Email", index: 1, day: 2, purpose: "What you do and what happens next, with the booking link" },
  { step: 3, channel: "Text", index: 2, day: 4, purpose: "One question that is easy to answer, to restart the thread" },
  { step: 4, channel: "Email", index: 2, day: 7, purpose: "How the job actually runs — remove the uncertainty that stalls people" },
  { step: 5, channel: "Text", index: 3, day: 11, purpose: "Offer to answer the one thing holding them up" },
  { step: 6, channel: "Email", index: 3, day: 16, purpose: "Local proof — real reviews and real work, no invented names" },
  { step: 7, channel: "Text", index: 4, day: 23, purpose: "Timing check — is this still on the list this season?" },
  { step: 8, channel: "Email", index: 4, day: 30, purpose: "What drives the price, honestly, so cost stops being a mystery" },
  { step: 9, channel: "Text", index: 5, day: 38, purpose: "Availability nudge, no pressure and no invented deadline" },
  { step: 10, channel: "Email", index: 5, day: 45, purpose: "The usual reason people wait, answered straight" },
  { step: 11, channel: "Text", index: 6, day: 52, purpose: "Last text — a direct, warm ask" },
  { step: 12, channel: "Email", index: 6, day: 58, purpose: "Final email — the straight ask with the booking link" },
  {
    step: 13,
    channel: "Email",
    index: 7,
    day: 60,
    purpose: "Close-out — we stop here, the door stays open, and the deal moves to Lost",
  },
];

const NURTURE_WORKFLOW_ID = "lead-nurture-no-booking";

/** The sequence metadata stamped onto both halves, so either document read on its
 *  own still says which workflow it belongs to, where that half is installed, and
 *  how the whole thing ends. */
export function nurtureMeta(half: "Email" | "Text"): NurtureSequenceMeta {
  const emails = NURTURE_SEQUENCE.filter((s) => s.channel === "Email").length;
  const texts = NURTURE_SEQUENCE.filter((s) => s.channel === "Text").length;
  const name = WORKFLOWS.find((w) => w.id === NURTURE_WORKFLOW_ID)?.name ?? "Lead Nurture — No Booking";
  return {
    workflowId: NURTURE_WORKFLOW_ID,
    workflowName: name,
    // Parenthesised rather than dash-joined for the reason spelled out in
    // workflowCoverage below: this workflow's own name already carries an em
    // dash, and a second one turns the string into something the scaffold
    // heuristic reads as a checklist.
    where: `${WORKFLOW_WHERE_PREFIX}${name} (the ${
      half === "Email" ? "email" : "text"
    } steps, sent from your business ${half === "Email" ? "email address" : "number"})`,
    lengthDays: NURTURE_SEQUENCE[NURTURE_SEQUENCE.length - 1]?.day ?? 60,
    totalSteps: NURTURE_SEQUENCE.length,
    emailCount: emails,
    textCount: texts,
    endsBy:
      "On day 60 the last email sends and the deal moves to Lost. It stops the moment they reply or book, and they come back in as a new lead the day they get in touch again — nothing is deleted.",
  };
}

/** The whole 13-step canvas, rendered for whichever half is being written. Both
 *  halves see ALL thirteen steps: an email written without knowing a text landed
 *  two days earlier repeats it word for word. */
function nurtureScheduleBlock(writing: "Email" | "Text"): string {
  const rows = NURTURE_SEQUENCE.map(
    (s) =>
      `  Step ${s.step} · Day ${s.day} · ${s.channel} ${s.index}${
        s.channel === writing ? "  ← you are writing this one" : ""
      } — ${s.purpose}`
  );
  return [
    `THE 60-DAY SEQUENCE — one workflow, thirteen steps, seven emails and six texts. You are writing the ${writing.toUpperCase()} half. Write them in this order and to these purposes; do not renumber, re-time, add or drop a step.`,
    ...rows,
    "",
    "RULES FOR THE WHOLE SEQUENCE:",
    "- These go to somebody who enquired and never booked. They are not a newsletter and not a broadcast. Every message reads like the owner typing on a phone between jobs.",
    "- Each half must know about the other: do not repeat a point the message two days earlier already made.",
    "- Every message carries ONE next step, and it is the booking link.",
    "- No invented deadline, no invented discount, no 'last chance'. If there is a genuine seasonal reason to act, say it plainly; if there is not, do not manufacture one.",
    "- The sequence stops the moment they reply or book. Never write a line that only makes sense if they have ignored every previous message.",
    "- The final email closes the loop kindly and leaves the door open — the deal moves to Lost, which is an internal state, so never tell the customer they have been marked anything.",
  ].join("\n");
}

// ── The site advisory block, verbatim ────────────────────────────────────────
// These four sentences are the scope language of the whole engagement. They used
// to be model-written inside the deleted landing call, which meant one bad
// regeneration could quietly drop the sentence that says we do not build
// websites. They are constants now: same words in every pack, every time.
const SITE_ADVISORY_SCOPE_NOTE =
  "These are advisory notes for whoever maintains the website; the page we build and host is the GoHighLevel booking page.";

const SITE_ADVISORY_RULES: string[] = [
  SITE_ADVISORY_SCOPE_NOTE,
  "The fastest version of all of this is repointing the existing buttons at the booking page and leaving the rest of the site alone.",
  "Never publish a review, a name or a photo that did not come from a real customer, however good the placeholder reads.",
  "Any response time promised on the page has to match what the automation actually does, or the page becomes a liability.",
];

/** The last rule again, on the booking page itself — that is the page whose
 *  promises our own automation has to keep. */
const BOOKING_PAGE_HONESTY_NOTE = SITE_ADVISORY_RULES[3];

// ── Where each string goes ───────────────────────────────────────────────────
// Stamped onto every surface. An operator with this document open and
// GoHighLevel open in the next tab should never have to guess which box a string
// belongs in — that guess is how a reassurance line ends up as a headline.
const SURFACE_WHERE = {
  bookingPage: "GoHighLevel → Sites → Booking page (the one page we build for you)",
  leadCaptureForm: "GoHighLevel → Sites → Forms → Lead capture, and the confirmation shown after it is sent",
  leadGate: `GoHighLevel → Sites → Forms → qualifying questions, and the on-screen replies ${PRODUCT_NAME} gives`,
  webchat: "GoHighLevel → Sites → Chat widget (the bubble on your website)",
  siteAdvisory: "Hand this to whoever looks after your website — it is advice, not work we do",
} as const;

const WORKFLOW_WHERE_PREFIX = "GoHighLevel → Automation → Workflows → ";

/** Destinations for the three asset groups that predate this file's `where`
 *  convention. Stamped for the same reason every other surface is: an asset with
 *  no stated destination cannot be installed without a guess, and these three are
 *  the ones most easily pasted into the wrong step. */
const BOOKING_ASSETS_WHERE =
  "GoHighLevel → Automation → Workflows → Booking Confirmation + Reminders, and No-Show Recovery — the confirmation email, the reminder email, the day-of text and the recovery messages";
const REVIEW_REQUEST_WHERE =
  "GoHighLevel → Automation → Workflows → Review Request — the text sent when a job is marked complete";
const THANK_YOU_WHERE =
  "GoHighLevel → Sites → the thank-you page a confirmed booking lands on, plus the messages that follow it";

/** Three workflows whose copy does NOT live on a workflow canvas, or whose
 *  destination is easy to get wrong in a way that matters. The owner
 *  notification is the one to be loud about: it is the only message in the whole
 *  pack that is not addressed to a customer, and pasting it into a customer-facing
 *  step would send the lead their own score. */
const WORKFLOW_WHERE_OVERRIDE: Record<string, string> = {
  "review-response": "GoHighLevel → Reputation → Reviews → the reply posted publicly under each new review",
  "social-dm-capture":
    "GoHighLevel → Automation → Workflows → Social DM Capture — the first reply, sent inside Facebook or Instagram",
  "owner-hot-lead-notification":
    "GoHighLevel → Automation → Workflows → Owner Hot-Lead Notification — this one goes to the owner's phone, never to the customer",
};

// ── Which workflows already have copy, and which this pack must write ────────
// THE RULE: a workflow in the build with no copy in the pack is unbilled work at
// the worst possible moment — the operator writing the owner notification by
// hand, inside the client's account, while the client watches.
//
// So the list of copy to generate is DERIVED from the catalogue rather than typed
// out: anything not named below is generated. Add a fifteenth workflow to the
// build and it appears in the prompt automatically; the failure mode is a
// harmless duplicate, never a silent gap.
const WORKFLOW_COPY_ELSEWHERE: Record<string, string> = {
  "booking-confirmation-reminders":
    "Booking & reminder assets — the confirmation email, the 24-hour reminder and the day-of text",
  "no-show-recovery": "Booking & reminder assets — the no-show recovery email and its two follow-up texts",
  "review-request": "Thank-you & post-job assets — the single review request that fires when a job is marked complete",
  "lead-nurture-no-booking":
    "The 60-day nurture sequence — seven emails and six texts, numbered onto this workflow's steps",
  "webchat-capture": "Conversion surfaces — the webchat launcher, greeting, details ask and away-message",
};

/** How many messages each generated workflow needs, and of what kind. Prompt
 *  guidance only — an id missing from here defaults to a single message, which is
 *  right for most of them. */
const WORKFLOW_COPY_SHAPE: Record<string, string> = {
  "instant-lead-response":
    "TWO messages: the text and the matching email, both sent within about a minute of the form arriving",
  "after-hours-auto-reply": "TWO messages: the text sent out of hours, and the matching email",
  "database-reactivation":
    "THREE messages: the opening text to the list, one gentle follow-up a week later, and the seasonal re-send. Every one must carry a one-tap way to hear nothing further",
  "review-response":
    "THREE public replies, one per kind of review: four or five stars, three stars, and one or two stars. The one-star reply never argues, never mentions a refund, and offers to take it to a phone call",
};

/**
 * Which of the fourteen are in THIS client's build.
 *
 * ONE CALL SITE FOR THE WHOLE ENGINE. Every prompt and every stamp below reads
 * this, so the Blueprint, the timeline and the asset pack cannot disagree with
 * each other — or with the toggles screen — about what the client is getting.
 * The fired leaks are threaded in because the evidence lock needs them: a
 * workflow justified by a measurement the client's own report prints must not be
 * absent from the build described three documents later.
 */
function clientBuild(ctx: GenerationContext): ResolvedWorkflow[] {
  return resolveClientBuild({
    intake: ctx.intake ?? null,
    // The REPORT set, not every raw fire — the lock's justification is "the
    // client's report carries this finding", so a fire the report never prints
    // must not lock anything.
    firedLeaks: ctx.leaks?.report ?? null,
    overrides: ctx.workflowToggles ?? null,
  });
}

/** The workflows this pack must write copy for, in catalogue order. */
export function workflowsNeedingCopy(ctx: GenerationContext): ResolvedWorkflow[] {
  return clientBuild(ctx).filter((r) => r.on && !(r.workflow.id in WORKFLOW_COPY_ELSEWHERE));
}

/**
 * Is every workflow in the build accounted for?
 *
 * Returns problems, never throws — same contract as verifyWorkflowCatalogue(),
 * and for the same reason: this checks static data that is right or wrong the
 * moment it is written, so the place to catch it is a test or a verify script,
 * not an import in a live app. Empty array = every workflow has somewhere its
 * copy comes from.
 */
export function verifyWorkflowCopyCoverage(): string[] {
  const problems: string[] = [];
  const ids = new Set(WORKFLOWS.map((w) => w.id));
  for (const id of Object.keys(WORKFLOW_COPY_ELSEWHERE))
    if (!ids.has(id))
      problems.push(
        `WORKFLOW_COPY_ELSEWHERE names "${id}", which is not a workflow in workflow-catalogue.ts.`
      );
  for (const id of Object.keys(WORKFLOW_COPY_SHAPE))
    if (!ids.has(id))
      problems.push(`WORKFLOW_COPY_SHAPE names "${id}", which is not a workflow in workflow-catalogue.ts.`);
  // Belt: with the derivation above this cannot fail, which is the point of
  // asserting it — if it ever does, the derivation has been replaced by a list.
  const generated = new Set(
    WORKFLOWS.filter((w) => !(w.id in WORKFLOW_COPY_ELSEWHERE)).map((w) => w.id)
  );
  for (const w of WORKFLOWS)
    if (!generated.has(w.id) && !(w.id in WORKFLOW_COPY_ELSEWHERE))
      problems.push(`Workflow "${w.id}" has no copy anywhere in the pack.`);
  return problems;
}

/**
 * EVERY STRING THIS MODULE PUTS IN A CLIENT'S DOCUMENT WITHOUT ASKING THE MODEL.
 *
 * Generated copy is scanned at three boundaries — generation, save and export —
 * so a banned word the model writes is caught. Stamped copy was never scanned by
 * anything, because it never existed as model output: it is typed into this file
 * by a person, ships verbatim, and a slip in it fails every pack silently and
 * identically. That is a worse failure than a bad generation, not a lesser one:
 * "search ranking" in a scope sentence would hard-fail Law 2 on every document
 * this engine ever produced.
 *
 * So the stamped strings are exported as data and the test suite runs the same
 * validator over them. It includes the workflow catalogue's own prose, because
 * this module is what carries that prose into a deliverable.
 */
export function stampedClientStrings(): string[] {
  const out: string[] = [
    ONE_TIME_INVESTMENT,
    MONTHLY_INVESTMENT,
    ...BUILD_ALSO_INCLUDED,
    ...BUILD_NOT_INCLUDED,
    ...SITE_ADVISORY_RULES,
    BOOKING_PAGE_HONESTY_NOTE,
    ...Object.values(SURFACE_WHERE),
    ...Object.values(WORKFLOW_COPY_ELSEWHERE),
    ...Object.values(WORKFLOW_WHERE_OVERRIDE),
    WORKFLOW_WHERE_PREFIX,
    BOOKING_ASSETS_WHERE,
    REVIEW_REQUEST_WHERE,
    THANK_YOU_WHERE,
    ...NURTURE_SEQUENCE.map((s) => s.purpose),
    nurtureMeta("Email").endsBy,
    nurtureMeta("Email").where,
    nurtureMeta("Text").where,
    ...ROADMAP_WINDOWS.flatMap((w) => [w.phase, w.window, w.investment]),
    `Qualification runs every day and is tuned every month, so it sits in the ${MONTHLY_INVESTMENT} monthly service rather than the one-time build.`,
  ];
  for (const w of WORKFLOWS) {
    out.push(
      w.name,
      w.whatItDoes,
      w.trigger,
      w.whatTheClientSees,
      `${WORKFLOW_WHERE_PREFIX}${w.name}`
    );
    if (w.applicability.kind !== "every_build") out.push(w.applicability.offWhen);
  }
  for (const p of PIPELINE) out.push(p.stage, p.whatItMeans, p.howALeadArrives, p.howALeadLeaves);
  return out.filter((s) => Boolean(s?.trim()));
}

/** Every workflow in this client's build with a pointer to where its copy lives.
 *  Fully stamped — the record that proves nothing was left without words. */
export function workflowCoverage(ctx: GenerationContext): WorkflowCopyCoverage[] {
  return clientBuild(ctx).map((r) => ({
    workflowId: r.workflow.id,
    workflowName: r.workflow.name,
    inThisBuild: r.on,
    // NOTE THE PUNCTUATION, IT IS NOT COSMETIC. Two of the fourteen workflow
    // names contain an em dash of their own ("Appointment Cancelled — Stop
    // Reminders"), so `Workflow copy — ${name}` produced THREE dash-separated
    // short fragments and tripped the validator's leaked-scaffold heuristic —
    // a fatal check, on a string we stamp into every pack. Quoting the name
    // keeps it to one separator.
    copyLivesIn: !r.on
      ? `Not in this build. ${r.because}`
      : WORKFLOW_COPY_ELSEWHERE[r.workflow.id] ?? `Written in this pack, under "${r.workflow.name}"`,
  }));
}

/** The catalogue as prompt material: what each workflow is, in the words the
 *  build already uses. */
function workflowBlock(resolutions: ResolvedWorkflow[], withShape: boolean): string {
  const rows = resolutions.flatMap((r) => {
    const w = r.workflow;
    const lines = [
      `- id: ${w.id}  ·  ${w.name}`,
      `    what it does: ${w.whatItDoes}`,
      `    fires when: ${w.trigger}`,
      `    what the client sees: ${w.whatTheClientSees}`,
    ];
    if (withShape) lines.push(`    write: ${WORKFLOW_COPY_SHAPE[w.id] ?? "ONE message"}`);
    return lines;
  });
  return rows.join("\n");
}

/** The canonical six-stage pipeline, rendered for a prompt. */
function pipelineBlock(): string {
  return [
    `THE PIPELINE WE CONFIGURE — exactly these six stages, in this order: ${PIPELINE_STAGES.join(" → ")}.`,
    ...PIPELINE.map(
      (s) =>
        `  ${s.stage} — ${s.whatItMeans} In: ${s.howALeadArrives} Out: ${s.howALeadLeaves}`
    ),
    "Do not add, rename, reorder or drop a stage. This is the board the client will actually look at every morning.",
  ].join("\n");
}

/** GRADE_VOICE, verbatim. Imported rather than restated — the honesty rules for
 *  measured / told / guessed are defined once in leak-narrative.ts, and a
 *  paraphrase here would be a second set of rules that eventually disagrees with
 *  the lint that enforces them. */
function gradeVoiceBlock(): string {
  return [
    "EVIDENCE GRADE — how much each finding is allowed to claim. Every leak in the governed set above carries a grade. Apply its rule to every sentence you write about that leak:",
    `  observed  — ${GRADE_VOICE.observed}`,
    `  disclosed — ${GRADE_VOICE.disclosed}`,
    `  inferred  — ${GRADE_VOICE.inferred}`,
  ].join("\n");
}

// ── Token-bucket rate limiter ────────────────────────────────────────────────
// The asset pack fires nine large gpt-4o calls (~6–7k tokens each, ~58k total).
// The org's gpt-4o tier caps at 30,000 tokens/minute, so firing them together —
// even pooled — bursts past the cap and 429s the whole run. This limiter meters
// outgoing token demand against a rolling 60s window so we stay under the ceiling
// by construction; the SDK's own retries (maxRetries on the client) then absorb
// any estimation drift. Tunable via env without a code change.
const TPM_WINDOW_MS = 60_000;
// Default to the model's typical tokens-per-minute ceiling so the bucket only
// throttles when it actually needs to. gpt-4o-mini is ~200k TPM (nine calls fit
// easily → no throttling, ~30s pack); gpt-4o on this account is ~30k. Override
// with OPENAI_ASSET_TPM if your account's limits differ.
const TPM_LIMIT = Number(
  process.env.OPENAI_ASSET_TPM ?? (ASSET_MODEL.includes("mini") ? 200_000 : 30_000)
);
// Leave headroom: our per-call estimate can drift below OpenAI's own accounting,
// and other calls (proposals, suggestions) may share the same minute.
const TPM_BUDGET = Math.max(6_000, Math.floor(TPM_LIMIT * 0.85));

let tpmWindowStart = Date.now();
let tpmUsed = 0;
// Serialize the check-and-reserve step so concurrent callers can't both pass the
// budget check before either increments the counter.
let tpmQueue: Promise<unknown> = Promise.resolve();

const sleep = (ms: number) => new Promise((r) => setTimeout(r, ms));

// Rough token estimate: ~4 chars/token for the prompt plus a reservation for the
// JSON completion. Intentionally a slight over-estimate so we pace conservatively.
function estimateTokens(prompt: string): number {
  return Math.ceil(prompt.length / 4) + 2_000;
}

async function acquireTokenBudget(estimate: number): Promise<void> {
  for (;;) {
    const now = Date.now();
    if (now - tpmWindowStart >= TPM_WINDOW_MS) {
      tpmWindowStart = now;
      tpmUsed = 0;
    }
    // A single call larger than the whole budget can never fit; let it through
    // (clamped) rather than spin forever — the SDK retry is the backstop.
    if (tpmUsed === 0 || tpmUsed + estimate <= TPM_BUDGET) {
      tpmUsed += estimate;
      return;
    }
    await sleep(TPM_WINDOW_MS - (now - tpmWindowStart) + 200);
  }
}

function reserveTokens(estimate: number): Promise<void> {
  const task = tpmQueue.then(() => acquireTokenBudget(estimate));
  // Keep the queue alive even if a reservation's caller later rejects.
  tpmQueue = task.then(
    () => undefined,
    () => undefined
  );
  return task;
}

/** Per-part completion ceiling. A part that blows past its ceiling is a runaway
 *  generation, and an unbounded call bills for every token of it.
 *
 *  RESTORED 2026-08-06 after being lost to a `git checkout` during the Phase 5
 *  roadmap deletion. Reconstructed from the compiled bundle in .next, which was
 *  built from the working tree before the revert, so the numbers are the ones
 *  that were actually running — not re-guessed.
 *
 *  `roadmap` is deliberately absent: that generation is retired (Phase 5). */
const PART_MAX_TOKENS: Record<string, number> = {
  file1: 8192,
  file2: 6144,
  file3: 6144,
  file4: 6144,
  file5: 6144,
  intelligence: 12288,
  infrastructure: 10240,
  supportingAssets: 10240,
  conversionSurfaces: 10240,
  workflowCopy: 12288,
};

/** Token spend for one generation run. Read after generateAssetPack to log what
 *  a pack actually cost. */
export const GENERATION_USAGE = {
  calls: 0,
  promptTokens: 0,
  completionTokens: 0,
  totalTokens: 0,
};

export interface GenerateOptions {
  /** Which part is being generated — picks the ceiling and names the part in a
   *  truncation error. */
  label?: string;
}

async function rawGenerateJson<T>(prompt: string, opts?: GenerateOptions): Promise<T> {
  const maxTokens = (opts?.label && PART_MAX_TOKENS[opts.label]) || 8192;
  await reserveTokens(estimateTokens(prompt));
  const response = await openai.chat.completions.create({
    model: ASSET_MODEL,
    messages: [{ role: "user", content: prompt }],
    response_format: { type: "json_object" },
    temperature: 0.7,
    max_tokens: maxTokens,
  });

  const usage = response.usage;
  GENERATION_USAGE.calls += 1;
  GENERATION_USAGE.promptTokens += usage?.prompt_tokens ?? 0;
  GENERATION_USAGE.completionTokens += usage?.completion_tokens ?? 0;
  GENERATION_USAGE.totalTokens += usage?.total_tokens ?? 0;

  // A ceiling hit means the JSON is CUT OFF mid-structure, so JSON.parse would
  // throw something unhelpful a few lines down. Fail here, naming the part and
  // the number to raise, rather than reporting a parse error.
  if (response.choices[0]?.finish_reason === "length") {
    throw new Error(
      `Generation truncated: "${opts?.label ?? "asset"}" hit its ${maxTokens}-token ceiling. ` +
        `Legitimate output should fit well under this — raise PART_MAX_TOKENS["${opts?.label ?? "default"}"] ` +
        `in asset-generation.ts only if this part genuinely grew.`
    );
  }

  const content = response.choices[0].message.content;
  if (!content) throw new Error("No content from AI");
  return JSON.parse(content) as T;
}

// Deep-walk every string value in a parsed JSON graph (for the voice scan).
function collectStringValues(value: unknown, out: string[] = []): string[] {
  if (typeof value === "string") out.push(value);
  else if (Array.isArray(value)) for (const v of value) collectStringValues(v, out);
  else if (value && typeof value === "object")
    for (const v of Object.values(value)) collectStringValues(v, out);
  return out;
}

// ── Flat-assertion enforcement (Law 13, paid pack) ───────────────────────────
// The FREE cold audit has run flatAssertionLint at its generation boundary since
// Law 13 landed; the $6,500 pack had nothing. Same lint, same one-regen shape —
// an INVISIBLE internal behavior ("they receive no follow-up", "calls go
// unanswered") may never be stated as flat fact in a document a client pays for.
//
// PROVENANCE-AWARE, and that is the whole point: the lint is only correct if it
// knows the PROVENANCE of the prose it is reading. A leak we actually measured, or
// one the client told us about, is a FACT — hedging it insults the client who
// answered the question. So the prose is not linted as one anonymous blob; each
// slice is paired with the evidence GRADE of the leak it is about (Phase 1; it
// used to carry the {tier, intakeConfirmed} pair), and flatAssertionLint's own
// belts (AssertionContext + PROTECTED_MARKERS) let it through untouched. Slices
// with no identifiable leak carry no context, which is the strict setting — the
// safe direction, since a false hit only costs a regen.
export interface AssertionScope extends AssertionContext {
  /** The prose slice to lint, already joined. */
  text: string;
}

/** Run the provenance-aware flat-assertion lint across every scoped prose slice
 *  and return the offending sentence fragments (empty = clean). */
function flatAssertionHits(scopes: AssertionScope[]): string[] {
  // The WHOLE scope is handed to the lint, not a hand-picked {tier,
  // intakeConfirmed} pair. AssertionScope extends AssertionContext, so
  // re-listing the fields here would silently drop any that get added to the
  // context later — which is exactly what happened to `grade` when it landed.
  return scopes.flatMap((s) => (s.text.trim() ? flatAssertionLint(s.text, s).hits : []));
}

// ── A DISCLOSURE MUST BE ATTRIBUTED (Phase 1) ────────────────────────────────
// The mirror image of the rule above, and the failure the owner named in his own
// words: "Never dress a disclosure up as something we detected." A leak the
// client TOLD us about is a fact, so nothing hedges it — but that exemption is
// only honest if the sentence says whose fact it is. "We found there's no
// follow-up sequence" hands the client their own intake answer back as our
// discovery, which is what makes an expensive report read like generic output.
//
// Caught HERE, at generation, so the model rewrites it while it still can. The
// same rule is fatal at the export boundary (validate-pack.ts), but by then the
// only remedy is an operator editing prose by hand.
//
// The vocabulary is PROTECTED_MARKERS via carriesProvenanceMarker — the one list
// the softener, the lint and the pack validator all consult.
function unattributedDisclosures(scopes: AssertionScope[]): string[] {
  return scopes
    .filter((s) => s.grade === "disclosed" && s.text.trim() && !carriesProvenanceMarker(s.text))
    .map((s) => s.text.trim().split(/(?<=[.!?])\s+/)[0].slice(0, 120));
}

/** The corrective addendum for an unattributed disclosure. Deliberately NOT the
 *  flat-assertion note: that one says "hedge this", which is the opposite of what
 *  a disclosed leak needs and would insult the client who answered the question. */
function disclosureAttributionNote(hits: string[]): string {
  if (!hits.length) return "";
  return `\n\nSPECIFICALLY: these lines describe something the CLIENT TOLD US at intake, but are written as if WE discovered it. Attribute each one to them in the same sentence ("You told us…", "Confirmed at intake…") and never as our own detection ("we found/scanned/observed"). Do NOT hedge them and do NOT add the kickoff-verification line — they already answered this question: ${hits
    .map((h) => `"${h}"`)
    .join(" ; ")}.`;
}

/** The corrective addendum naming the offending lines — worded exactly as the
 *  cold audit's, so both documents teach the model the same rewrite. */
function flatAssertionNote(hits: string[]): string {
  if (!hits.length) return "";
  return `\n\nSPECIFICALLY: these lines assert an INVISIBLE internal behavior as flat fact — you cannot see inside their operation. Rewrite each as pattern + visible-absence + conditional (name the visible ABSENCE, cite the industry pattern, then hedge with "likely/if that's how it works today"), or attribute it to its source ("you told us…", "your reviews mention…"): ${hits
    .map((h) => `"${h}"`)
    .join(" ; ")}.`;
}

// Part F1: EVERY generation call is voice-linted — including the email/SMS/booking
// copy that used to bypass governance. A banned word anywhere in the returned JSON
// triggers ONE corrective regeneration; we keep whichever draft is cleaner. This
// is the banned-word half of the governance boundary applied universally; the
// number/stat guard stays in generateGovernedJson where the allowed set is known.
//
// Law 13 rides on the SAME single regeneration (not a second mechanism): when a
// caller supplies `assertions`, its flat-assertion hits join the voice hits in
// the one corrective pass, and the cleaner of the two drafts still wins. The
// Phase 1 attribution rule rides on that same pass for the same reason — a third
// regeneration mechanism is a third thing that can silently stop running.
async function generateJson<T>(
  prompt: string,
  assertions?: (v: T) => AssertionScope[],
  opts?: GenerateOptions
): Promise<T> {
  const out = await rawGenerateJson<T>(prompt, opts);
  const firstScopes = assertions ? assertions(out) : [];
  const firstVoice = voiceLint(collectStringValues(out).join("\n")).hits;
  const firstFlat = flatAssertionHits(firstScopes);
  const firstUnattributed = unattributedDisclosures(firstScopes);
  const firstTotal = firstVoice.length + firstFlat.length + firstUnattributed.length;
  if (firstTotal === 0) return out;

  const voiceNote = firstVoice.length
    ? `Your previous draft used these banned words/phrases: ${firstVoice.join(", ")}.
Rewrite it in plain, direct language WITHOUT any of them (and without other marketing filler like "streamline", "robust", "leverage", "optimize the/your", "empower", "unlock").`
    : firstFlat.length
      ? "Your previous draft asserted things it cannot know."
      : "Your previous draft mis-attributed something it does know.";
  const corrective = `${prompt}

════════ VOICE CORRECTION (your previous draft broke the rules) ════════
${voiceNote}${flatAssertionNote(firstFlat)}${disclosureAttributionNote(
    firstUnattributed
  )} Return the same JSON shape.`;
  const retry = await rawGenerateJson<T>(corrective, opts);
  const retryScopes = assertions ? assertions(retry) : [];
  const retryHits =
    voiceLint(collectStringValues(retry).join("\n")).hits.length +
    flatAssertionHits(retryScopes).length +
    unattributedDisclosures(retryScopes).length;
  return retryHits <= firstTotal ? retry : out;
}

// Governance boundary (decision 2/4 + enforcement memory): after a deliverable is
// generated, scan its prose for numbers outside the allowed set (stat guard) and
// banned voice tics (voice lint). On violation, regenerate ONCE with a corrective
// addendum naming the exact offenders, then return the cleaner of the two.
// Purely additive: when no leak context is present the base generation is returned
// untouched, so legacy/no-detection runs are unaffected.
async function generateGovernedJson<T>(
  prompt: string,
  ctx: GenerationContext,
  extractText: (v: T) => string,
  assertions?: (v: T) => AssertionScope[]
): Promise<T> {
  const out = await generateJson<T>(prompt, assertions);
  if (!ctx.leaks) return out;
  const check = (v: T) => {
    const text = extractText(v);
    const stat = statGuard(text, ctx.leaks!.allowedNumbers);
    const voice = voiceLint(text);
    // Law 13 and the Phase 1 attribution rule ride in the same governance check,
    // so a stat/voice regen also carries those corrections instead of losing them.
    const scopes = assertions ? assertions(v) : [];
    const flat = flatAssertionHits(scopes);
    const unattributed = unattributedDisclosures(scopes);
    return {
      violations: [...stat.violations, ...voice.hits, ...flat, ...unattributed],
      flatHits: flat,
      unattributed,
      ok: stat.ok && voice.ok && flat.length === 0 && unattributed.length === 0,
    };
  };
  const first = check(out);
  if (first.ok) return out;

  const corrective = `${prompt}

════════ GOVERNANCE CORRECTION (your previous draft violated the rules) ════════
Your previous draft used disallowed content: ${first.violations.join(", ")}.
Rewrite it WITHOUT any of those. Every number you print MUST come from the governed leak set / allowed figures above — invent no percentages, multipliers, or dollar amounts. Remove the banned words entirely.${flatAssertionNote(
    first.flatHits
  )}${disclosureAttributionNote(first.unattributed)} Return the same JSON shape.`;
  const retry = await generateJson<T>(corrective, assertions);
  const second = check(retry);
  // Keep whichever draft has fewer violations; prefer the retry on a tie.
  return second.violations.length <= first.violations.length ? retry : out;
}

// ── FILE 1: Growth Audit ─────────────────────────────────────────────────────
// It used to be "Growth Audit + Landing Page": the audit AND a full page of
// hero/problem/solution/offer/testimonial copy for a landing page nobody builds.
// The page copy is gone from here (see `landingPage` in src/types/index.ts) — the
// booking page, the form, the webchat and their own site now get their copy from
// generateConversionSurfaces(), addressed to the surface it goes on. What is left
// is the audit: the diagnosis, the competitor read, the market intelligence and
// the internal sales material.

// Law 13 scopes for file 1: the DIAGNOSTIC prose only. The offer/positioning copy
// underneath is customer-facing marketing, not a claim about how this business
// runs, so it is deliberately out of scope — hedging it would damage perfectly
// honest sales copy. No per-leak provenance exists on this shape, so every slice
// is linted strictly (the lint's own provenance markers still apply).
function file1Assertions(f: GrowthAuditFile): AssertionScope[] {
  return [
    { text: f.executiveSummary ?? "" },
    { text: f.growthAudit?.overview ?? "" },
    ...(f.growthAudit?.findings ?? []).map((x) => ({ text: x.finding ?? "" })),
    ...(f.revenueLeaks ?? []).map((x) => ({
      text: [x.issue, x.whyItMatters].filter(Boolean).join("\n"),
    })),
    ...(f.conversionBottlenecks ?? []).map((x) => ({ text: x.problem ?? "" })),
  ];
}

