// ── V2 STRATEGIC COMPONENT: Growth Leak Intelligence ─────────────────────────
// Powers Deliverable 1 (Growth Leak Intelligence Report): a 9-metric scorecard,
// a deep prioritized leak analysis, ranked revenue wins, an executive summary,
// and consulting-grade strategic recommendations.

// Decision 1: the nine scorecard axes are fixed by the taxonomy, in SCORECARD_AREAS
// order. The model writes each axis's narrative; the numeric score is set
// deterministically from gradeAreas afterward (decision 2), never model-invented.
const NINE_AXIS_LIST = SCORECARD_AREAS.map(
  (a, i) => `${i + 1}. ${SCORECARD_DISPLAY_NAMES[a]}`
).join("\n");

// Part D · per-axis diagnostic briefing. For each of the nine scorecard axes,
// state deterministically whether a leak actually fired against it — so the
// model conditions each axis's diagnosis on its OWN fired leaks (D2) and writes
// a CLEAN axis as neutral/positive only, inventing no problem (D1). This is the
// generation-side half of Part D; validate-pack enforces the same at output.
/** The scorecard axes where NOTHING fired, by client-facing name. Used twice: to
 *  tell the model which axes it must state are fine, and to stamp those lines in
 *  if it leaves them out. */
function cleanAxisNames(ctx: GenerationContext): string[] {
  if (!ctx.leaks) return [];
  const dirty = new Set<ScorecardArea>();
  for (const f of ctx.leaks.report) if (f.leak.scorecardArea) dirty.add(f.leak.scorecardArea);
  return SCORECARD_AREAS.filter((a) => !dirty.has(a)).map((a) => SCORECARD_DISPLAY_NAMES[a]);
}

/**
 * Which leaks carry the CLIENT'S OWN numbers, and which rest on a benchmark.
 *
 * The distinction decides how a dollar sentence has to be written, and getting it
 * backwards fails in both directions: labelling the client's own figure an
 * "estimate" wastes the intake answer they gave us and makes a real number look
 * invented, while presenting an industry benchmark as their number is a claim we
 * cannot support (and a fatal validator check at the export boundary). The math
 * engine already knows which is which — mathMode is REAL when the estimate was
 * computed from operator-entered client figures — so it is stated here rather
 * than left to the model to infer from the wording of a frame.
 */
function clientNumberBlock(ctx: GenerationContext): string {
  if (!ctx.leaks) return "";
  const real = ctx.leaks.inputs.filter((li) => li.mathMode === "REAL");
  if (!real.length)
    return [
      "DOLLAR FIGURES — NONE OF THEM ARE THIS CLIENT'S OWN NUMBERS. Every supplied figure rests on an industry benchmark or a stated assumption, so every sentence carrying a dollar amount must say so IN THAT SAME SENTENCE (\"assuming…\", \"an industry benchmark\", \"an estimate\"). Never write a figure as though the client gave it to us.",
    ].join("\n");
  return [
    `DOLLAR FIGURES — THESE LEAKS USE THE CLIENT'S OWN NUMBERS (they gave them at intake): ${real
      .map((li) => li.name)
      .join(" · ")}.`,
    "For those: attribute the figure to them in the same sentence — \"based on the numbers you provided\" — and do NOT label it an assumption or an estimate. It is their number; calling it a guess wastes the answer they gave us.",
    "For every OTHER dollar figure: it rests on a benchmark or an assumption, and the sentence carrying it must say so in that same sentence.",
    "Either way, print only the figures supplied in the fired-leak block. Never derive, round or combine them yourself.",
  ].join("\n");
}

function scorecardAreaBriefing(ctx: GenerationContext): string {
  if (!ctx.leaks) return "";
  const byArea = new Map<ScorecardArea, FiredLeak[]>();
  for (const f of ctx.leaks.report) {
    const area = f.leak.scorecardArea;
    if (!area) continue;
    (byArea.get(area) ?? byArea.set(area, []).get(area)!).push(f);
  }
  const lines = SCORECARD_AREAS.map((area, i) => {
    const name = SCORECARD_DISPLAY_NAMES[area];
    const fired = byArea.get(area) ?? [];
    const grade = ctx.leaks!.grades[area];
    if (!fired.length) {
      return `${i + 1}. ${name} — CLEAN (grade ${grade}). NO leak fired here. Diagnosis MUST be neutral or positive: state it holds up / nothing is bleeding here. Invent NO problem, gap, or loss. Do NOT borrow another axis's leak.`;
    }
    const symptoms = fired.map((f) => f.leak.symptom).join(" · ");
    return `${i + 1}. ${name} — LEAK(S) FIRED (grade ${grade}). Diagnose ONLY from these, which belong to THIS axis: ${symptoms}`;
  });
  return [
    "════════ PER-AXIS DIAGNOSIS MAP (Part D — bind each axis's diagnosis to its OWN fired leaks) ════════",
    "For each of the nine axes below, write its diagnosis ONLY from the leaks listed for that axis.",
    "A CLEAN axis (no leak) gets neutral/positive copy — never a fabricated problem, never another axis's leak.",
    "",
    ...lines,
  ].join("\n");
}

// Overwrite each metric's score with the deterministic grade and force the metric
// set to the nine canonical axes, in order. The model supplies prose only.
// A scorecard axis with no fired leak grades to exactly 95 (gradeAreas special-
// cases zero-leak axes). Its diagnosis/cause/evidence must read neutral — the
// model sometimes invents a problem there anyway (Part D). We detect the same
// problem vocabulary the validator does and, when a clean axis trips it, replace
// the offending prose with an honest neutral line so a 95 never asserts a leak.
const CLEAN_AXIS_PROBLEM_VOCAB =
  /\b(losing|lose|lost|bleed(?:ing)?|hemorrhag\w*|missing|missed|gap|weak(?:ness)?|leak(?:ing|s)?|broken|failing|fails|poor|hurting|costing|costs you|slipping|drop-?off|dropping|underperform\w*|deficien\w*|struggl\w*)\b/i;

function applyDeterministicGrades(
  intel: GrowthIntelligence,
  grades: Record<ScorecardArea, number>
): GrowthIntelligence {
  const modelMetrics = intel.scorecard?.metrics ?? [];
  const metrics = SCORECARD_AREAS.map((area, i) => {
    const name = SCORECARD_DISPLAY_NAMES[area];
    const m = modelMetrics[i] ?? modelMetrics.find((x) => x?.name === name);
    const score = grades[area];
    let diagnosis = m?.diagnosis ?? "";
    let cause = m?.cause ?? "";
    let evidence = m?.evidence ?? "";
    // Clean axis (95 = no leak fired): purge any fabricated problem. Phrasing
    // deliberately avoids every word in CLEAN_AXIS_PROBLEM_VOCAB.
    if (score === 95) {
      if (CLEAN_AXIS_PROBLEM_VOCAB.test(`${diagnosis} ${cause} ${evidence}`)) {
        diagnosis = `${name} is performing in line with best-practice benchmarks — nothing on this axis needs attention right now.`;
        cause = "";
        // Keep evidence non-empty (Law 6) but strip the fabricated problem: a
        // clean axis's evidence is simply that no conversion issue surfaced here.
        if (CLEAN_AXIS_PROBLEM_VOCAB.test(evidence))
          evidence = `No conversion issue surfaced on ${name} — it meets the benchmark for a business of this profile.`;
      }
    }
    return {
      name,
      score,
      rubric: m?.rubric ?? "",
      evidence,
      diagnosis,
      whyItMatters: m?.whyItMatters ?? "",
      cause,
      expectedBenefit: m?.expectedBenefit ?? "",
    };
  });
  return { ...intel, scorecard: { ...intel.scorecard, metrics } };
}

// ── Part I · deterministic leak-analysis stamping ────────────────────────────
// Defects 1–4: the renderer only ever sees the persisted leakAnalysis, never the
// LeakContext — so identity (leak name + axis), whitelisted stats WITH citations,
// the computed benchmark/real math, the industry-pattern body, and the kickoff
// line must be STAMPED onto each item here from the fired taxonomy, not trusted
// from the model. We rebuild the list as exactly one item per FIRED IN-SCOPE leak
// (out-of-scope leaks get no section), merging the model's prose by best match.

function normLeak(s: string): string {
  return s.toLowerCase().replace(/[^a-z0-9]+/g, " ").trim();
}

function leakTokenOverlap(a: string, b: string): number {
  const bs = new Set(normLeak(b).split(" ").filter((w) => w.length > 2));
  return normLeak(a)
    .split(" ")
    .filter((w) => w.length > 2 && bs.has(w)).length;
}

/** Best-match a model-written leak title back to the FIRED taxonomy leak, using
 *  the same overlap+containment heuristic stampLeakAnalysis uses to merge prose.
 *  Read-only (no consumption of matches) because the flat-assertion lint just
 *  needs each item's PROVENANCE — its tier and whether the client confirmed it —
 *  and undefined (no match) is the safe answer: it lints at the strict setting. */
function matchLeakInput(hay: string, inputs: LeakInput[]): LeakInput | undefined {
  let bestLi: LeakInput | undefined;
  let best = 0;
  for (const li of inputs) {
    const overlap = leakTokenOverlap(hay, li.name);
    const contains =
      normLeak(hay).includes(normLeak(li.name)) || normLeak(li.name).includes(normLeak(hay));
    const score = overlap + (contains ? 3 : 0);
    if (score > best) {
      best = score;
      bestLi = li;
    }
  }
  return best > 0 ? bestLi : undefined;
}

// A2 (render half): a leak whose dollar figure is a SUBSET of another leak's
// (after-hours calls ARE missed calls) must never be added into a total. The
// arithmetic and the plain-English note both live in leak-narrative
// (reconcileLeakTotal / overlapNote), but the renderer reads a SAVED pack, which
// only carries LeakAnalysisItem — so the two overlap fields are stamped through
// here, alongside the tier and the math, and travel in the persisted JSON.
//
// Both fields are declared on LeakAnalysisItem itself (src/types/index.ts), so
// they are part of the persisted pack's contract rather than keys that merely
// ride along structurally, and src/lib/exporters/deliverables.ts reads them back
// off the plain type with no cast.

export function stampLeakAnalysis(
  intel: GrowthIntelligence,
  inputs: LeakInput[]
): GrowthIntelligence {
  // In-scope leaks only — an out-of-scope flag never earns its own leak section.
  const inScope = inputs.filter((li) => li.scorecardArea);
  if (!inScope.length) return intel;

  const model = intel.leakAnalysis ?? [];
  const used = new Set<number>();

  // Cap dollar-bearing math frames at 2 per document (Defect 1: "≤2 per doc").
  // Frames are consumed in fired-rank order, so the top leaks keep their dollars.
  let dollarFramesLeft = 2;
  const carriesDollar = (frame: string | null) =>
    !!frame && /\$\s?\d/.test(frame) && /\/mo\b/.test(frame);

  const items: LeakAnalysisItem[] = inScope.map((li) => {
    // Best-effort match to a model item so we keep its richer prose.
    let mi = -1;
    let best = 0;
    model.forEach((m, idx) => {
      if (used.has(idx)) return;
      const hay = `${m.area ?? ""} ${m.leakName ?? ""}`;
      const overlap = leakTokenOverlap(hay, li.name);
      const contains =
        normLeak(hay).includes(normLeak(li.name)) ||
        normLeak(li.name).includes(normLeak(hay));
      const score = overlap + (contains ? 3 : 0);
      if (score > best) {
        best = score;
        mi = idx;
      }
    });
    const m = best > 0 && mi >= 0 ? model[mi] : undefined;
    if (m) used.add(mi);

    const areaLabel = li.scorecardArea
      ? SCORECARD_DISPLAY_NAMES[li.scorecardArea as ScorecardArea] ??
        li.scorecardArea
      : "";

    // The dollar figure is STAMPED from the deterministic math estimate (li.dollar),
    // never the model's integers (determinism fix 1). The frame and the structured
    // callout share the same ≤2-per-doc cap and the same source numbers, so the
    // rendered range is always mathematically consistent with the mathFrame in the
    // same document. A leak whose $ figure is dropped for the cap loses BOTH the
    // frame and the callout together.
    let mathFrame: string | undefined = li.mathFrame ?? undefined;
    let dollarImpact: DollarImpact | undefined;
    if (li.dollar && carriesDollar(li.mathFrame)) {
      if (dollarFramesLeft > 0) {
        dollarFramesLeft--;
        dollarImpact = {
          leadVolumeBasis: li.dollar.leadVolumeBasis,
          effectSize: li.dollar.effectSize,
          avgValueBasis: li.dollar.avgValueBasis,
          monthlyLow: li.dollar.low,
          monthlyHigh: li.dollar.high,
          formula: li.dollar.formula,
          usesBenchmarkValue: li.dollar.usesBenchmarkValue,
        };
      } else {
        mathFrame = undefined; // drop the dollar figure beyond the 2nd leak
      }
    }

    return {
      // Identity is deterministic (Defect 2): title = taxonomy leak name.
      area: li.name,
      leakName: li.name,
      scorecardArea: areaLabel,
      evidenceTier: li.tier,
      // THE HONESTY GATE, STAMPED (Phase 1). Derived exactly once — at detection,
      // by gradeOf — and carried from there: FiredLeak → LeakInput → here. It is
      // never recomputed at this call site and never read off the model's output,
      // for the same reason the tier beside it isn't: a hallucinated "observed"
      // would switch off every hedge in the document. This is the field the
      // renderer picks the evidence label from and the two fatal grade checks in
      // validate-pack.ts key on, so if it could drift from what the detector
      // actually found, the document's voice would drift with it.
      evidenceGrade: li.grade,
      evidence: m?.evidence ?? li.evidence.join(" · "),
      explanation: m?.explanation ?? li.revenueMechanism,
      businessImpact: m?.businessImpact ?? li.symptom,
      dollarImpact,
      difficulty: m?.difficulty ?? "medium",
      priority: m?.priority ?? (li.tier === "OBSERVED" ? "high" : "medium"),
      recommendedFix: m?.recommendedFix ?? "",
      owner: m?.owner ?? "us",
      // Deterministic quantification + pattern + kickoff (Defects 1, 3, 4).
      allowedStats: li.allowedStats.length ? li.allowedStats : undefined,
      mathFrame,
      industryPattern: li.industryPattern ?? undefined,
      kickoffLine: li.requiresKickoffLine ? KICKOFF_VERIFICATION_LINE : undefined,
      // Confirmed-at-intake BENCHMARK leaks render as fact (label + framing) and
      // carry NO kickoff line — stamped so the renderer + validator agree.
      intakeConfirmed: li.intakeConfirmed || undefined,
      // Quantifiable = the taxonomy actually gave this leak a stat or a surviving
      // math frame. Uses the POST-cap `mathFrame` so a leak whose dollar figure we
      // intentionally dropped for the ≤2 cap isn't later flagged as unquantified.
      quantifiable: li.allowedStats.length > 0 || Boolean(mathFrame),
      // A2: carried through so the renderer can exclude this figure from the
      // total AND say out loud that it did. Only meaningful while the figure is
      // actually shown, so they ride with dollarImpact.
      overlapsWith: dollarImpact ? li.overlapsWith ?? undefined : undefined,
      overlapNote: dollarImpact ? li.overlapNote ?? undefined : undefined,
    };
  });

  return { ...intel, leakAnalysis: items };
}

async function generateIntelligence(ctx: GenerationContext): Promise<GrowthIntelligence> {
  const prompt = `${STYLE_RULES}

${contextHeader(ctx)}

TASK: Produce the GROWTH LEAK INTELLIGENCE layer — the diagnostic core of the report that diagnoses exactly where THIS business loses the enquiries it ALREADY GETS on the way to becoming customers. CONVERSION ONLY (Law 2): never diagnose how to get more traffic/leads.

${gradeVoiceBlock()}

${clientNumberBlock(ctx)}

THEIR OWN WEBSITE IS ADVISORY. You may state what is measurably true of their site (a buried booking path, a slow mobile page, no way to book) as a finding, because it is where a leak becomes visible. You may NOT prescribe work on it: no redesign, no rebuild, no page speed work, no new page. We do not build, host or maintain websites. The one page we build is the booking page inside their GoHighLevel sub-account. Anything about their own site is written as advice for whoever looks after it, and that advisory copy is produced elsewhere in this pack — keep it out of the leak analysis.

SAY WHAT IS ALREADY FINE, OUT LOUD. A report that lists only problems reads as a sales document, and an owner who knows one part of his operation is solid stops believing the parts he cannot check. Every scorecard axis with no fired leak must be stated plainly as holding up — not skipped, not softened into a near-problem, and never given an invented gap.

${scorecardAreaBriefing(ctx)}

Write a narrative for EACH of these NINE conversion-axis dimensions, in this exact order and with these exact names. For each, give its rubric (what it measures, relative to what good looks like) and the specific real evidence behind it (Law 6). DO NOT assign the numeric score yourself — leave "score" as 0; the score is computed deterministically from the fired-leak set and will be filled in for you. PART D DISCIPLINE — bind each axis to the PER-AXIS DIAGNOSIS MAP above: an axis's diagnosis/cause/evidence may reference ONLY the leak(s) listed under THAT axis; a CLEAN axis (no leak fired) MUST read neutral or positive — it holds up, nothing is bleeding there — and must NOT invent a problem, gap, or loss, nor borrow another axis's leak. The nine dimensions:
${NINE_AXIS_LIST}
Do NOT invent extra axes, rename these, or drop any.

Then a deep GROWTH LEAK ANALYSIS across the conversion path only (speed-to-lead, lead capture, lead qualification, follow-up/nurture, booking friction, no-show recovery, on-page CTA, on-page form, on-page trust placement, mobile conversion). For EACH leak: concrete evidence (grounded in the signals), a strategic explanation, the business impact, a DOLLAR IMPACT with visible math (Law 5), implementation difficulty, priority, and who deploys the fix (almost always "us"). Open the executive summary with the single most damning dollar-quantified leak (Law 8) — never a compliment.

Then rank the FASTEST REVENUE WINS by dollar impact ÷ effort. Then STRATEGIC RECOMMENDATIONS framed as the done-for-you scope ("What We Deploy") — name ${PRODUCT_NAME} as the ongoing qualification/routing engine (the retainer). No fluff, no fake statistics, no guarantees.

Do NOT author dollarImpact — the dollar range, formula, and bases are computed deterministically and stamped in for you AFTER generation, so any figure you put there is discarded. Omit dollarImpact entirely. When you reference a dollar figure in prose (e.g. the executive summary's #1 leak), use ONLY a figure that appears in the "dollar/spend framing" line of the fired-leak block above — never invent your own.

Return JSON in EXACTLY this shape:
{
  "executiveSummary": {
    "narrative": "Open with the #1 dollar-quantified conversion leak (the gut-punch), then the core problem and the single biggest recovery opportunity. 3-5 sentences. TIER DISCIPLINE (Part C3): an OBSERVED leak may be stated as fact; a BENCHMARK leak must be hedged (typically/most/if that holds here) and framed as an industry pattern, never asserted about this business. NEVER assert an internal response-time fact the scrape cannot see (e.g. 'you take 8 hours to reply', 'your calls go to voicemail') — the outside view can't measure that; frame it as the industry pattern to verify. If any dollar figure uses a benchmark customer value, note once that plugging in their real average customer value makes every figure exact.",
    "biggestOpportunities": ["..."],
    "biggestThreats": ["..."],
    "mostUrgentFixes": ["..."],
    "quickWins": ["..."],
    "whatHoldsUp": ["ONE plain sentence per scorecard axis where NO leak fired, naming the axis and saying it is fine — e.g. 'Booking: someone can book a time online without calling you, and that path works.' State it as a finding, not a compliment, and invent no problem here"]
  },
  "scorecard": {
    "overallReadout": "2-4 sentence read on overall conversion health and where the biggest leaks are",
    "metrics": [
      {"name": "Speed to Lead", "score": 0, "rubric": "what this measures, relative to what good looks like", "evidence": "the specific real data behind the read", "diagnosis": "...", "whyItMatters": "...", "cause": "...", "expectedBenefit": "..."}
    ]
  },
  "leakAnalysis": [
    {"area": "Speed-to-Lead", "evidenceTier": "OBSERVED|EVIDENCED|BENCHMARK — copy the [tier: …] of this leak from the governed set above EXACTLY", "evidence": "...", "explanation": "...", "businessImpact": "...", "difficulty": "low|medium|high", "priority": "critical|high|medium|low", "recommendedFix": "...", "owner": "us"}
  ],
  "fastestWins": [
    {"opportunity": "...", "impact": "$ range + one phrase", "difficulty": "low|medium|high", "speed": "e.g. under a week"}
  ],
  "strategicRecommendations": ["what we deploy — done-for-you scope, ${PRODUCT_NAME} named as the ongoing retainer engine"]
}

Provide EXACTLY 9 scorecard metrics named and ordered as listed (score left at 0 — it is filled in deterministically). Provide leakAnalysis items covering ONLY the fired leaks from the governed set above (omit dollarImpact — it is stamped in deterministically). Provide 4-6 fastestWins and 4-6 strategicRecommendations.${
    cleanAxisNames(ctx).length
      ? ` Provide EXACTLY ${cleanAxisNames(ctx).length} whatHoldsUp lines — one for each of these axes, which had NO leak fire: ${cleanAxisNames(
          ctx
        ).join(" · ")}.`
      : " Leave whatHoldsUp empty — every axis had a leak fire."
  }`;
  const intel = await generateGovernedJson<GrowthIntelligence>(
    prompt,
    ctx,
    intelligenceText,
    // Law 13, tier-aware: each leak's prose is linted against the provenance of
    // the FIRED leak it describes, so an OBSERVED or intake-confirmed finding is
    // never flagged (and so never hedged away in the corrective rewrite).
    (v) => intelligenceAssertions(v, ctx.leaks?.inputs ?? [])
  );
  if (!ctx.leaks) return intel;
  const graded = applyDeterministicGrades(intel, ctx.leaks.grades);
  const withCleanFindings = stampCleanFindings(graded, cleanAxisNames(ctx));
  return stampLeakAnalysis(withCleanFindings, ctx.leaks.inputs);
}

/**
 * A CLEAN AXIS IS A FINDING, AND IT GETS SAID.
 *
 * The prompt asks for one "this holds up" line per axis where nothing fired. The
 * model complies most of the time, which is exactly the problem with leaving it
 * there: the failure is silent and it always fails in the same direction —
 * towards a document that lists nothing but problems and therefore reads as a
 * sales pitch. So any axis the model skipped gets a stamped line here.
 *
 * The stamped wording deliberately avoids every word in the clean-axis problem
 * vocabulary the validator scans for (losing, gap, weak, missing…), because a
 * sentence about something that is FINE must not contain the vocabulary of
 * something that is broken.
 */
export function stampCleanFindings(intel: GrowthIntelligence, cleanAxes: string[]): GrowthIntelligence {
  if (!cleanAxes.length) return intel;
  const written = (intel.executiveSummary?.whatHoldsUp ?? []).filter((s) => s?.trim());
  const alreadyNamed = (axis: string) =>
    written.some((line) => line.toLowerCase().includes(axis.toLowerCase()));
  const filled = [...written];
  for (const axis of cleanAxes) {
    if (alreadyNamed(axis)) continue;
    filled.push(
      `${axis}: nothing surfaced here. It holds up against what we would expect for a business of this profile, so it is not on the fix list.`
    );
  }
  return {
    ...intel,
    executiveSummary: { ...intel.executiveSummary, whatHoldsUp: filled },
  };
}

// Gather the free-text surfaces of the intelligence layer for the stat/voice guard.
function intelligenceText(i: GrowthIntelligence): string {
  const es = i.executiveSummary;
  return [
    es?.narrative,
    ...(es?.biggestOpportunities ?? []),
    ...(es?.biggestThreats ?? []),
    ...(es?.mostUrgentFixes ?? []),
    ...(es?.quickWins ?? []),
    i.scorecard?.overallReadout,
    ...(i.leakAnalysis ?? []).flatMap((l) => [
      l.evidence,
      l.explanation,
      l.businessImpact,
      l.recommendedFix,
      l.dollarImpact?.formula,
    ]),
    ...(i.fastestWins ?? []).map((w) => w.impact),
    ...(i.strategicRecommendations ?? []),
  ]
    .filter(Boolean)
    .join("\n");
}

// The grade-aware Law 13 scopes for the intelligence layer. This is the ONLY
// deliverable where per-leak provenance is knowable, because every leakAnalysis
// item traces back to a fired taxonomy leak that carries its evidence grade — so
// it is the only one that can safely be told "this is a fact, leave it alone".
function intelligenceAssertions(
  i: GrowthIntelligence,
  inputs: LeakInput[]
): AssertionScope[] {
  const scopes: AssertionScope[] = [];
  // The executive summary speaks across leaks, so it has no single provenance
  // and is linted strictly. A sentence that states its own source ("you told
  // us…", "based on the numbers you provided") is still let through by the
  // lint's PROTECTED_MARKERS belt, which is exactly the intended escape hatch.
  const narrative = i.executiveSummary?.narrative;
  if (narrative) scopes.push({ text: narrative });

  for (const l of i.leakAnalysis ?? []) {
    const li = matchLeakInput(`${l.area ?? ""} ${l.leakName ?? ""}`, inputs);
    scopes.push({
      // The diagnosis prose only. recommendedFix describes what WE deploy, not
      // an operational claim about them, so hedging it would be wrong.
      text: [l.evidence, l.explanation, l.businessImpact].filter(Boolean).join("\n"),
      // Provenance comes from the fired taxonomy leak, NEVER the model's own
      // evidenceTier/evidenceGrade strings — both are stamped over
      // deterministically after generation, so trusting them here would let a
      // hallucinated "observed" switch the lint off.
      //
      // The GRADE is what the lint keys on now; the pair travels with it purely
      // so nothing is lost if a leak somehow reaches here without one (an
      // unmatched title, a caller predating the grade). No match at all means no
      // context, which lints at the strict setting.
      grade: li?.grade,
      tier: li?.tier,
      intakeConfirmed: li?.intakeConfirmed,
    });
  }
  return scopes;
}

// ── V2 STRATEGIC COMPONENT: Acquisition Infrastructure ───────────────────────
// Powers Deliverable 2 (Client Acquisition Infrastructure Blueprint): the
// 6-stage CONVERSION-PATH funnel (Capture → Qualify → Speed-to-Lead → Nurture →
// Book → Show-Up & No-Show Recovery) and the CRM-agnostic pipeline blueprint +
// lead tiers. Conversion-only (Law 2): no traffic/lead-gen stages. Everything is
// done-for-you (Law 3); the Qualify stage is LeadGate running continuously = the
// retainer (Law 4).

async function generateInfrastructure(ctx: GenerationContext): Promise<AcquisitionInfrastructure> {
  const resolutions = clientBuild(ctx);
  const inBuild = resolutions.filter((r) => r.on);
  const leftOut = resolutions.filter((r) => !r.on);

  const prompt = `${STYLE_RULES}

${contextHeader(ctx)}

TASK: Produce the CLIENT ACQUISITION INFRASTRUCTURE architecture for THIS business — the operating blueprint for how the leads they ALREADY get turn into booked, shown-up customers. CONVERSION PATH ONLY (Law 2): this is NOT about getting more traffic or leads. Do not include Traffic Sources, ads, SEO, social, content, or referral as stages. Everything below is DONE FOR YOU (Law 3) — frame each stage as what WE deploy, never as the owner's to-do list.

THE BUILD IS FIXED AND IT IS LISTED BELOW. Do not invent a workflow, rename one, merge two, or describe a system that is not in the list. If something you would recommend is not there, it is not in this engagement and it does not go in this document.

THE TWO PRICES BUY DIFFERENT THINGS, AND MIXING THEM UP IN WRITING COSTS REAL MONEY. ${ONE_TIME_INVESTMENT} is the one-time build. ${MONTHLY_INVESTMENT} a month is ${PRODUCT_NAME} — the qualification and routing engine — plus us running and tuning it and the monthly report. NEVER write a sentence that puts ${PRODUCT_NAME}, lead qualification, lead scoring or scoring thresholds inside the one-time build: a client holding a document that says they already bought it can win that argument with the first invoice. If a sentence has to mention both, it must say "monthly" (or "the retainer", or "ongoing") in that same sentence.

WE DO NOT BUILD WEBSITES. No page structure, no redesign, no rebuild, no hosting, no launch of anything except the booking page inside their GoHighLevel sub-account. Findings about their existing site are advice for whoever looks after it, and that advice lives in another part of this pack.

Part A — the 6-stage conversion path, in this EXACT order:
1. Capture — turn the enquiries they already get into captured leads (form, click-to-call, chat, social message).
2. Qualify (${PRODUCT_NAME}) — ${PRODUCT_NAME} scores and routes every lead automatically. THIS STAGE IS THE MONTHLY SERVICE, NOT THE ONE-TIME BUILD: it runs every day and is tuned every month, so set isRetainer=true and say plainly in whatWeDeploy that it is included in the monthly, not something switched on once and left.
3. Speed-to-Lead / Instant Response — every new enquiry gets a first touch inside about a minute.
4. Nurture — leads who did not book keep hearing from you for 60 days.
5. Book — a real time on a real calendar, confirmed and reminded.
6. Show-Up & No-Show Recovery — reminders, and recovery when somebody does not turn up.
For EACH stage: its role in the conversion path, the current break point (grounded in the real signals — be specific to THIS business), what WE deploy to fix it (done-for-you), the owner ("us" for everything we build; "you" ONLY for genuine human steps like answering a qualified lead or running the consult), whether it is the monthly service (only stage 2 = true), and a KPI to track. Set owner="us" on every stage except where a human owner step is unavoidable.

Part B — THE ONE-TIME BUILD (${ONE_TIME_INVESTMENT}). These are the workflows that go into this client's GoHighLevel sub-account. Each one is already described below in the words we use for it; your ONLY job per workflow is one or two sentences of "whyForThisBusiness" — why this one matters for THIS business, tied to its fired leaks and real signals above. Do not restate what it does, do not rename it, do not invent one. If a workflow has no specific reason for this business, return an empty string rather than a generic sentence.

${workflowBlock(inBuild, false)}
${
  leftOut.length
    ? `\nLEFT OUT OF THIS CLIENT'S BUILD (do not write copy or reasons for these; they are listed only so you do not reference them): ${leftOut
        .map((r) => r.workflow.name)
        .join(" · ")}`
    : ""
}

Part C — ${pipelineBlock()}
For EACH pipeline stage your ONLY job is "reviewProcess": how the owner and we keep that column honest — when it is looked at, what moves, who moves it. Entry and exit criteria are already fixed and will be filled in for you; do not write them.

Part D — THE MONTHLY SERVICE (${MONTHLY_INVESTMENT} per month), which is ${PRODUCT_NAME} plus us running and tuning the system. Lead scoring and qualification belong HERE, not in the build: a scoring rule that is never revisited is worth nothing by month three. Write what actually happens every month, then the 4 lead tiers — 90–100 Priority Lead, 70–89 Qualified Lead, 50–69 Nurture Lead, Below 50 Low Fit Lead — each with meaning, action, response time, owner (${PRODUCT_NAME} routes automatically; the owner answers Priority himself), and follow-up method. Finish with one sentence saying plainly why qualification is the monthly service rather than part of the one-time build.

Return JSON in EXACTLY this shape:
{
  "funnel": {
    "overview": "2-4 sentence read on how the conversion path should operate end-to-end for this business — from a captured lead to a shown-up customer, with ${PRODUCT_NAME} qualifying continuously",
    "stages": [
      {"stage": "Capture", "role": "...", "currentWeakness": "...", "whatWeDeploy": "...", "owner": "us", "isRetainer": false, "kpi": "..."}
    ]
  },
  "build": {
    "overview": "2-4 sentences on what gets built inside their GoHighLevel sub-account and what changes the day it is switched on. No page-building, no website language.",
    "workflows": [
      {"workflowId": "instant-lead-response", "whyForThisBusiness": "one or two sentences tied to THIS business's fired leaks, or an empty string"}
    ]
  },
  "crmPipeline": {
    "overview": "2-3 sentence read on how the pipeline WE configure is operated and reviewed",
    "stages": [
      {"stage": "${PIPELINE_STAGES[0]}", "reviewProcess": "..."}
    ]
  },
  "ongoing": {
    "overview": "2-3 sentences on what the monthly service is and what the owner gets out of it every month",
    "whatRunsEveryMonth": ["4-6 concrete things that happen every month — qualification running, thresholds tuned, copy adjusted, the monthly report"],
    "leadTiers": [
      {"tier": "Priority Lead", "range": "90–100", "meaning": "...", "action": "...", "responseTime": "...", "owner": "...", "followUpMethod": "..."}
    ],
    "whyItIsNotInTheBuild": "one plain sentence"
  }
}

Provide EXACTLY 6 funnel stages (in the order above, Qualify = ${PRODUCT_NAME} with isRetainer=true), one build.workflows entry per workflow listed in Part B using its exact id, EXACTLY ${
    PIPELINE_STAGES.length
  } pipeline stages named exactly as in Part C, and EXACTLY 4 lead tiers in the order listed.`;
  // Law 13: "currentWeakness" is where this document states what is broken
  // INSIDE their operation — the exact place a flat assertion the cold scan
  // cannot support would appear. Everything else here describes what we build.
  const infra = await generateJson<AcquisitionInfrastructure>(prompt, (a) =>
    (a.funnel?.stages ?? []).map((s) => ({ text: s.currentWeakness ?? "" }))
  , { label: "infrastructure" });
  return stampBuild(infra, resolutions);
}

/**
 * Stamp the parts of the Blueprint that are the same in every build.
 *
 * WHAT THE MODEL IS ALLOWED TO KEEP: the funnel prose, the build overview, one
 * "why this matters here" sentence per workflow, each pipeline column's review
 * process, the monthly narrative and the four tiers. Everything else — every
 * workflow name, trigger and description, the six stage names with their entry
 * and exit rules, both prices, what else is in the build and what is not — comes
 * from the catalogue or from a constant.
 *
 * The reason is not tidiness. Those are the facts a client will hold us to. A
 * paraphrased workflow name means the document and the sub-account disagree; an
 * invented pipeline stage means the board he opens does not match the one he was
 * sold; a model-written price is a number we then have to honour.
 */
export function stampBuild(
  infra: AcquisitionInfrastructure,
  resolutions: ResolvedWorkflow[]
): AcquisitionInfrastructure {
  const modelWorkflows = new Map(
    (infra.build?.workflows ?? []).map((w) => [w.workflowId, w.whyForThisBusiness ?? ""])
  );
  const workflows: BuiltWorkflow[] = resolutions.map((r) => {
    const w: WorkflowDefinition = r.workflow;
    return {
      workflowId: w.id,
      name: w.name,
      whatItDoes: w.whatItDoes,
      trigger: w.trigger,
      whatTheClientSees: w.whatTheClientSees,
      // The model's sentence only. A workflow it forgot still appears, with a
      // blank reason — an unexplained workflow is a smaller problem than a
      // missing one, and a fabricated reason is the biggest problem of the three.
      whyForThisBusiness: r.on ? modelWorkflows.get(w.id) ?? "" : "",
      excluded: r.on ? undefined : true,
      exclusionReason: r.on ? undefined : r.because,
    };
  });

  // The pipeline: six stages, named and defined by the catalogue. The model's
  // reviewProcess is merged in by stage name; anything else it wrote is dropped.
  const modelStages = new Map(
    (infra.crmPipeline?.stages ?? []).map((s) => [s.stage?.trim().toLowerCase() ?? "", s])
  );
  const stages: CrmStage[] = PIPELINE.map((p) => ({
    stage: p.stage,
    entryCriteria: p.howALeadArrives,
    exitCriteria: p.howALeadLeaves,
    ownership: "Deployed by us",
    reviewProcess: modelStages.get(p.stage.toLowerCase())?.reviewProcess ?? p.whatItMeans,
  }));

  return {
    ...infra,
    crmPipeline: {
      ...infra.crmPipeline,
      stages,
      // Lead tiers moved to `ongoing` — qualification is the monthly service, and
      // leaving a copy here would put it back inside the build by implication.
      leadTiers: undefined,
    },
    build: {
      overview: infra.build?.overview ?? "",
      investment: `${ONE_TIME_INVESTMENT}, one-time`,
      workflows,
      alsoIncluded: BUILD_ALSO_INCLUDED,
      notIncluded: BUILD_NOT_INCLUDED,
    },
    ongoing: {
      overview: infra.ongoing?.overview ?? "",
      investment: `${MONTHLY_INVESTMENT} per month`,
      whatRunsEveryMonth: infra.ongoing?.whatRunsEveryMonth ?? [],
      leadTiers: infra.ongoing?.leadTiers ?? [],
      whyItIsNotInTheBuild:
        infra.ongoing?.whyItIsNotInTheBuild ??
        `Qualification runs every day and is tuned every month, so it sits in the ${MONTHLY_INVESTMENT} monthly service rather than the one-time build.`,
    },
  };
}

// ── V2 STRATEGIC COMPONENT: Supporting Assets ────────────────────────────────
