// ── V2 STRATEGIC COMPONENT: Implementation & Optimization Timeline ───────────
// Powers Deliverable 4. WE implement everything (Law 3). The timeline is the
// SHAPE OF THE OFFER, which is why the old "Setup / Stabilize / Ongoing
// Optimization" phases were wrong: they described a project, not a purchase.
//
//   Days 1–14   the build          — the CAD $6,500 one-time
//   Go-Live     a single moment    — defined precisely, because "when does this
//                                    start working?" is the question every owner
//                                    asks and vagueness here becomes a support
//                                    thread three weeks later
//   Days 15–90  the monthly        — the CAD $1,000/month
//
// "Done" is measurable conversion outcomes, never activities.

/** Which week of the build each workflow lands in. Week one is the spine —
 *  nothing else is worth switching on until an enquiry gets answered, a missed
 *  call gets a text back and a booking confirms itself. An id not listed defaults
 *  to week two, so a workflow added to the catalogue still lands somewhere. */
const WORKFLOW_BUILD_WEEK: Record<string, "week_one" | "week_two"> = {
  "instant-lead-response": "week_one",
  "missed-call-text-back": "week_one",
  "after-hours-auto-reply": "week_one",
  "booking-confirmation-reminders": "week_one",
  "appointment-cancelled-stop-reminders": "week_one",
  "webchat-capture": "week_one",
  "owner-hot-lead-notification": "week_one",
  "no-show-recovery": "week_two",
  "lead-nurture-no-booking": "week_two",
  "review-request": "week_two",
  "review-response": "week_two",
  "social-dm-capture": "week_two",
  "text-to-pay": "week_two",
  "database-reactivation": "week_two",
};

/** The workflows whose results only exist in the Days 15–90 window: the 60-day
 *  sequence does not finish inside the build, reviews accumulate, and the
 *  reactivation list is sent in batches on an agreed rhythm. They are BUILT in
 *  the first fortnight and JUDGED in the second window. */
const WORKFLOW_MATURES_LATER = new Set<string>([
  "lead-nurture-no-booking",
  "database-reactivation",
  "review-request",
  "review-response",
  "no-show-recovery",
  "text-to-pay",
]);

/** The three windows, fixed. Phase name, window, price and retainer flag are
 *  stamped — a model-authored price is a number we would then have to honour. */
const ROADMAP_WINDOWS: {
  phase: string;
  window: string;
  isRetainerPhase: boolean;
  investment: string;
}[] = [
  { phase: "Build", window: "Days 1–14", isRetainerPhase: false, investment: `${ONE_TIME_INVESTMENT}, one-time` },
  {
    phase: "Go-Live",
    window: "Day 14 — the day it starts answering for you",
    isRetainerPhase: false,
    investment: "Included in the build",
  },
  {
    phase: "Ongoing",
    window: "Days 15–90 and beyond",
    isRetainerPhase: true,
    investment: `${MONTHLY_INVESTMENT} per month`,
  },
];

/** Which workflow names belong in each window, by name, from the catalogue. */
/** The workflows in this client's build, split into the two build weeks. An id
 *  with no entry in the map defaults to week two, so a workflow added to the
 *  catalogue still lands somewhere real instead of vanishing from the timeline. */
function buildWeeks(resolutions: ResolvedWorkflow[]): { one: string[]; two: string[] } {
  const on = resolutions.filter((r) => r.on).map((r) => r.workflow);
  return {
    one: on.filter((w) => (WORKFLOW_BUILD_WEEK[w.id] ?? "week_two") === "week_one").map((w) => w.name),
    two: on.filter((w) => (WORKFLOW_BUILD_WEEK[w.id] ?? "week_two") === "week_two").map((w) => w.name),
  };
}

/** Which workflow names belong in each of the three windows, by phase index:
 *  0 Build (all of them, tagged with the week they land in), 1 Go-Live (all of
 *  them — go-live is the day the whole build starts running), 2 Ongoing (only the
 *  ones whose results exist in that window). */
function roadmapWorkflowNames(resolutions: ResolvedWorkflow[], phaseIndex: number): string[] {
  const on = resolutions.filter((r) => r.on).map((r) => r.workflow);
  if (phaseIndex === 0) {
    const weeks = buildWeeks(resolutions);
    return [
      ...weeks.one.map((n) => `${n} (week one)`),
      ...weeks.two.map((n) => `${n} (week two)`),
    ];
  }
  if (phaseIndex === 1) return on.map((w) => w.name);
  return on.filter((w) => WORKFLOW_MATURES_LATER.has(w.id)).map((w) => w.name);
}

async function generateRoadmap(ctx: GenerationContext): Promise<GrowthRoadmap> {
  const resolutions = clientBuild(ctx);
  const { one: weekOne, two: weekTwo } = buildWeeks(resolutions);

  const prompt = `${STYLE_RULES}

${contextHeader(ctx)}

TASK: Produce the IMPLEMENTATION & OPTIMIZATION TIMELINE for THIS business — what we build in the first fortnight, what happens the day it goes live, and what the following months actually look like. DONE FOR YOU (Law 3): every phase is what WE do. The only things the owner does are genuine human steps — approving copy, answering the enquiries worth answering himself, showing up to the jobs.

THREE PHASES, in this EXACT order. The names, the windows and the money are fixed; write the substance.

1. Build — Days 1–14 — ${ONE_TIME_INVESTMENT}, one-time. We stand the whole system up inside their GoHighLevel sub-account. Nothing here is a task for the owner. Sequence the work by the leaks THIS report actually surfaced, biggest first. Week one is the spine: ${weekOne.join(
    ", "
  ) || "the core response and booking workflows"}. Week two is everything that builds on it: ${
    weekTwo.join(", ") || "the follow-up, review and payment workflows"
  }. isRetainerPhase=false.

2. Go-Live — the single day it starts answering for them. This is NOT a stretch of work, it is a moment, and it has to be defined precisely enough that the owner knows the exact point at which his phone behaviour changes. Three parts:
   · whatSwitchesOn — what we turn on, in order (the tracked number starts taking calls and forwarding to the phone he already answers; the booking calendar starts accepting real bookings; every workflow moves from draft to live; the pipeline starts receiving; the chat box goes on the site if it can be placed).
   · whatWeNeedFromYou — the SHORT, honest list of things only he can do: approve the copy, confirm the hours and availability on the calendar, forward his existing number or publish the new one, get the chat snippet onto the site (or tell us who can), confirm who controls the Google listing, hand over the past-customer list if there is one. Nothing else lands on him.
   · whatLiveMeans — the test that settles it, in one sentence: a real enquiry arriving through his own number or form gets an answer inside about a minute, appears in the pipeline at ${
     PIPELINE_STAGES[0]
   }, and is followed up without anybody at his end doing anything.
   isRetainerPhase=false.

3. Ongoing — Days 15–90 and beyond — ${MONTHLY_INVESTMENT} per month. ${PRODUCT_NAME} qualifying and routing every enquiry, us watching the numbers and tuning the system, and a report every month. This is also when the slower workflows show what they are worth: the 60-day follow-up sequence reaches its end and starts closing deals out, review replies accumulate, and any past-customer campaign has been through a batch. isRetainerPhase=true. Name ${PRODUCT_NAME}.

For EACH phase: objective, the concrete actions WE take, and a "done" definition stated as MEASURABLE CONVERSION OUTCOMES ("median first reply under five minutes", "no missed call goes without a text back"), never activities. Do not invent a number that is not in the data above.

ONE HARD RULE ACROSS PHASES 1 AND 2: neither of them may claim ${PRODUCT_NAME}, lead qualification, lead scoring or scoring thresholds as something the one-time build delivers. Those belong to phase 3, the monthly service. If a Build or Go-Live line genuinely has to mention the qualification engine — connecting it, for instance — that same line must also say it is the monthly service that runs and tunes it. Written the other way round, the timeline gives away the ${MONTHLY_INVESTMENT}-a-month engine inside the ${ONE_TIME_INVESTMENT} fee.

Return JSON in EXACTLY this shape:
{
  "overview": "2-3 sentences: the fortnight, the day it goes live, then the months — and what 'working' looks like in booked-job terms",
  "phases": [
    {"phase": "Build", "window": "Days 1–14", "objective": "...", "deployActions": ["..."], "owner": "us", "doneDefinition": ["measurable conversion outcome"], "isRetainerPhase": false,
     "goLive": {"whatSwitchesOn": ["..."], "whatWeNeedFromYou": ["..."], "whatLiveMeans": "..."}}
  ]
}

Provide EXACTLY 3 phases in the order listed, 3-6 deployActions and 2-4 doneDefinition outcomes each. Include the "goLive" object on the SECOND phase ONLY, and omit it from the other two. The Build phase's actions must map to the actual leaks in this report, sequenced by dollar impact.`;
  // Law 13: the overview and each phase objective are the only slots here that
  // describe the CURRENT state; deployActions and doneDefinition describe our
  // future work and would read absurdly if hedged.
  const roadmap = await generateJson<GrowthRoadmap>(prompt, (r) => [
    { text: r.overview ?? "" },
    ...(r.phases ?? []).map((p) => ({ text: p.objective ?? "" })),
  ]);
  return stampRoadmapWindows(roadmap, resolutions);
}

/**
 * Stamp the fixed half of the timeline: the three phase names, their windows,
 * which phase is the retainer, what each window costs, and which workflows land
 * in it. The model keeps the objective, the actions, the "done" definitions and
 * the go-live detail.
 *
 * Owner is forced to "us" on every phase. It is not a judgement call — the whole
 * timeline is work we do, the client's own steps are enumerated inside the
 * go-live block, and an owner value the model spells differently ("we", "US") is
 * a fatal validator failure at the export boundary for no reason at all.
 */
export function stampRoadmapWindows(
  roadmap: GrowthRoadmap,
  resolutions: ResolvedWorkflow[]
): GrowthRoadmap {
  const model = roadmap.phases ?? [];
  const phases = ROADMAP_WINDOWS.map((w, i) => {
    const m = model[i];
    return {
      phase: w.phase,
      window: w.window,
      objective: m?.objective ?? "",
      deployActions: m?.deployActions ?? [],
      owner: "us" as const,
      doneDefinition: m?.doneDefinition ?? [],
      isRetainerPhase: w.isRetainerPhase,
      investment: w.investment,
      workflowsInThisWindow: roadmapWorkflowNames(resolutions, i),
      // The go-live block belongs to the middle phase and nowhere else. Taking it
      // from whichever phase the model attached it to means a model that put it on
      // phase 1 does not silently lose it.
      goLive: i === 1 ? m?.goLive ?? model.find((p) => p?.goLive)?.goLive : undefined,
    };
  });
  return { ...roadmap, phases };
}

// ══════════════════════════════════════════════════════════════════════════════
// D3 · CONVERSION SURFACES — the copy, addressed to the box it goes in
// ══════════════════════════════════════════════════════════════════════════════
//
// THIS REPLACED THE LANDING-PAGE CALL. The old call wrote a landing-page
// specification — nine page sections, a page order, a CTA inventory, deployment
// notes, a tool to build it with. We do not build, host, redesign or deploy
// websites. The one page ReclaimedHQ builds is the booking page inside the
// client's GoHighLevel sub-account, so that call was writing copy for a surface
// the offer does not contain.
//
// The words were mostly right and the destination was wrong, so the copy is
// REPOINTED rather than deleted:
//
//   booking page      ← headlines, subheads, buttons, the reassurance line under
//                       the button, the proof line, the section order, the FAQ
//   lead-capture form ← the form's own words and everything after the submit,
//                       including the emergency route out of the automation
//   LeadGate          ← the words wrapped around the qualifying questions
//   webchat           ← launcher, greeting, details ask, away-message
//   site advisory     ← the diagnosis of their OWN site, explicitly advisory,
//                       carrying the four standing rules verbatim
//
// EVERY SURFACE CARRIES ITS `where`. An operator with this document open and
// GoHighLevel open in the next tab must never have to guess which box a string
// belongs in — that guess is how a reassurance line ends up as a headline.
//
// NEVER "a paid-traffic destination". That framing implies an advertising
// programme we neither run nor sell, and it would turn the booking page into the
// end of a funnel we do not own.

// Law 13 scopes for the surfaces call: the site ADVISORY prose only. Everything
// else here is customer-facing copy — hedging a headline would wreck it — but the
// advisory notes make claims about a business we have only looked at from the
// outside, and "your form goes nowhere" is exactly the invisible-internal
// assertion the lint exists to catch.
function surfaceAssertions(s: ConversionSurfaces): AssertionScope[] {
  const advisory = s.siteAdvisory;
  if (!advisory) return [];
  return [
    { text: advisory.summary ?? "" },
    ...(advisory.notes ?? []).map((n) => ({
      text: [n.whatWeSaw, n.recommendation].filter(Boolean).join("\n"),
    })),
  ];
}

async function generateConversionSurfaces(ctx: GenerationContext): Promise<ConversionSurfaces> {
  const psi = ctx.intel.performance;
  const hasPsi = Boolean(psi?.available);
  const perfLine = hasPsi
    ? `Real PageSpeed data IS available: mobile score ${psi?.mobile?.performanceScore ?? "n/a"}, mobile LCP ${psi?.mobile?.metrics.lcpSeconds ?? "n/a"}s, mobile CLS ${psi?.mobile?.metrics.cls ?? "n/a"}. You may state what those numbers mean for somebody trying to book on a phone. You may NOT prescribe the fix — no image, CSS, hosting or speed work. It is flagged, never fixed.`
    : `No live PageSpeed data was captured. Say so plainly rather than guessing at their site's speed.`;

  const prompt = `${STYLE_RULES}

${contextHeader(ctx)}

TASK: Write the CONVERSION COPY for the surfaces we actually build and run for THIS business, plus written advice about their own website. Every string you produce goes in a specific box, and the section it lands in NAMES that box — so write each one for its destination, not as generic page copy.

THE FIVE DESTINATIONS:

1. THE BOOKING PAGE — ${SURFACE_WHERE.bookingPage}. This is the ONE page we build and brand. It exists to turn an enquiry that already exists into a booked, qualified visit. It is NOT an advertising destination and nothing about it may imply that visits to it are being bought or sent. Write: three headline options and three subheadline options (the owner picks one at build time, so all three must stand on their own), the primary and secondary buttons, the short reassurance line that sits directly UNDER the button, one credible above-the-fold proof line, the FAQ block, and the page section by section IN ORDER — each section with the finished words that go in it, not a description of what it should say. Sections normally run: hero, the problem in the customer's own terms, how the work actually goes, proof, the booking step, and a closing ask. One of the two buttons may be a tap-to-call on the tracked number if that is how this trade's customers prefer to start.

2. THE LEAD-CAPTURE FORM — ${SURFACE_WHERE.leadCaptureForm}. The form's own headline and intro, the submit button, and what the person sees the moment they send it: what happens next, by when, and the way out if it is urgent. THE EMERGENCY ROUTE IS NOT OPTIONAL — somebody with a burst pipe or a dead furnace must be told how to reach a human immediately instead of waiting on an automated sequence.

3. THE QUALIFYING QUESTIONS — ${SURFACE_WHERE.leadGate}. NOT the questions themselves (they are written elsewhere in this pack and must not be restated here — two copies of a question set is two question sets that can disagree). Write the words AROUND them: the line above them that says why they are being asked, two to four short framing lines that sit beside individual questions, and the two on-screen replies — one for a lead that scores as urgent and worth dropping everything for, one for everybody else. Both replies are warm; only the timeline differs, and the timeline must be one the automation actually keeps.

4. THE WEBCHAT — ${SURFACE_WHERE.webchat}. The text on the chat bubble itself, the opening greeting, the way it asks for a name and number so the conversation can carry on as a text, and the away-message for somebody who opens it at 9pm. The away-message says when they will hear back and offers the booking link; it never promises a reply that will not happen.

5. ADVICE ABOUT THEIR OWN WEBSITE — ${SURFACE_WHERE.siteAdvisory}. ADVISORY ONLY. We do not build, rebuild, redesign, host or maintain websites, and nothing here may read as work we are doing. Write a short summary and four to six specific notes: what we saw, what we would change, how much it matters. Say what is measurably true (a booking path that takes four clicks to find, a phone number that is not tappable on a phone, a hero that does not say what they do or where). ${perfLine} The single most valuable note is usually the cheapest one: point the buttons they already have at the booking page and leave the rest of the site alone.

RULES THAT APPLY TO EVERY STRING HERE:
- NEVER INVENT PROOF. No testimonial, no customer name, no quote, no result that is not in the data above. Where proof belongs and none exists, write a labelled placeholder — "[Insert verified customer review]", "[Insert the number of years in business]" — and leave it for the owner to fill in. A recognisable fake name in a client's own document is the fastest way to lose them.
- NO INVENTED URGENCY. No countdown, no "limited spots", no deadline that does not exist. If there is a real seasonal reason to act, say it plainly.
- NEVER PROMISE A RESPONSE TIME THE AUTOMATION DOES NOT KEEP. Any timing you write on a page or a confirmation has to match what the workflows actually do.
- PLAIN OWNER LANGUAGE: calls, jobs, quotes, booked work. Not "conversions", not "funnels", not "ROI".
- Specific to this trade and this city. A headline that would work for any business in any town is a headline nobody reads.

Return JSON in EXACTLY this shape:
{
  "bookingPage": {
    "headlineOptions": ["3 sharp, intent-matched headlines — each one must work on its own"],
    "subheadlineOptions": ["3 subheadlines"],
    "primaryButton": "the button text, e.g. 'Book a service visit'",
    "secondaryButton": "the alternative route, e.g. 'Request a written quote'",
    "reassuranceLine": "the short line directly under the button — real proof or a labelled placeholder",
    "proofLine": "one credible above-the-fold proof line, or a labelled placeholder",
    "sectionOrder": [{"name": "Hero", "purpose": "what this section is for", "copy": "the finished words for this section — paste-ready, no brief, no placeholder except a labelled [Insert verified …] one"}],
    "faq": [{"question": "a real objection somebody has before booking", "answer": "..."}]
  },
  "leadCaptureForm": {
    "formHeadline": "...",
    "formIntro": "one or two lines above the fields",
    "submitButton": "...",
    "postSubmitHeadline": "...",
    "postSubmitCopy": "what happens next and by when — matched to what the automation actually does",
    "emergencyRoute": "how to reach somebody immediately if it cannot wait"
  },
  "leadGate": {
    "openingLine": "why we are asking these questions, in one line",
    "questionIntros": ["2-4 short framing lines"],
    "priorityAcknowledgement": "what an urgent, high-value enquiry sees on screen",
    "standardAcknowledgement": "what everybody else sees"
  },
  "webchat": {
    "launcherLabel": "the words on the chat bubble",
    "greeting": "the opening message",
    "detailsAsk": "how it asks for a name and number",
    "awayMessage": "what somebody opening it out of hours sees"
  },
  "siteAdvisory": {
    "summary": "3-5 sentences of advisory read on their existing site as a way of getting booked — measured facts, no prescription of design or speed work",
    "notes": [{"area": "e.g. Buttons", "whatWeSaw": "...", "recommendation": "...", "priority": "critical|high|medium|low"}]
  }
}

Provide EXACTLY 3 headlineOptions and 3 subheadlineOptions, 5-8 booking-page sectionOrder entries, 5-8 FAQ items, 2-4 questionIntros, and 4-6 siteAdvisory notes. Do not emit any other keys — the destination labels and the standing rules are added afterwards and must not be written by you.`;

  return stampSurfaceDestinations(await generateJson<ConversionSurfaces>(prompt, surfaceAssertions, { label: "conversionSurfaces" }));
}

/**
 * STAMPED, NOT TRUSTED. Two kinds of string are fixed here.
 *
 * The `where` labels, because the whole point of this deliverable is that an
 * operator never guesses which box a string goes in — a label the model
 * paraphrases differently on every run is a label he stops reading.
 *
 * And the four standing rules, because they are the scope language of the
 * engagement. The sentence that says we do not build websites has to be identical
 * in every pack, and one unlucky regeneration must not be able to drop it.
 *
 * Exported for the same reason `stampLeakAnalysis` is: the golden fixture has to
 * be stamped by THIS function, or the committed sample slowly stops resembling
 * what generation actually produces and every check that reads it is checking
 * fiction.
 */
export function stampSurfaceDestinations(out: ConversionSurfaces): ConversionSurfaces {
  return {
    ...out,
    bookingPage: {
      ...out.bookingPage,
      where: SURFACE_WHERE.bookingPage,
      honestyNote: BOOKING_PAGE_HONESTY_NOTE,
    },
    leadCaptureForm: { ...out.leadCaptureForm, where: SURFACE_WHERE.leadCaptureForm },
    leadGate: { ...out.leadGate, where: SURFACE_WHERE.leadGate },
    webchat: { ...out.webchat, where: SURFACE_WHERE.webchat },
    siteAdvisory: {
      ...out.siteAdvisory,
      where: SURFACE_WHERE.siteAdvisory,
      scopeNote: SITE_ADVISORY_SCOPE_NOTE,
      standingRules: SITE_ADVISORY_RULES,
    },
  };
}

// ══════════════════════════════════════════════════════════════════════════════
// D3 · WORKFLOW COPY — a message for every workflow in the build
// ══════════════════════════════════════════════════════════════════════════════
//
// THE GAP THIS CLOSES. The build is fourteen workflows. The pack shipped copy for
// about half of them — the booking confirmations, the reminders, the no-show
// recovery, the review request, the nurture sequence — and said nothing at all
// about the owner's own hot-lead notification, the review replies, the payment
// text, the reactivation campaign or the social auto-reply. Every one of those
// still had to be written, so it got written by the operator, by hand, inside the
// client's account, on the day the client was watching. That is unbilled work in
// a different voice.
//
// The list is DERIVED FROM THE CATALOGUE, never typed out: any workflow not named
// in WORKFLOW_COPY_ELSEWHERE gets copy here. Add a fifteenth workflow to the
// build and it appears in this prompt on the next run — the failure mode is a
// harmless duplicate, never a silent gap.

async function generateWorkflowCopy(ctx: GenerationContext): Promise<WorkflowCopyPack> {
  const needed = workflowsNeedingCopy(ctx);
  const coverage = workflowCoverage(ctx);

  // Nothing to write (every workflow switched off) — return the coverage record
  // anyway, because "there is no copy here" is itself information the operator
  // needs, and skipping the call saves a model round-trip for nothing.
  if (!needed.length) return { assets: [], coverage };

  const prompt = `${STYLE_RULES}

${contextHeader(ctx)}

TASK: Write the actual messages for the workflows we install in THIS business's GoHighLevel sub-account. These are not examples and not a specification — every string here is pasted into a real workflow and sent to a real customer, so write them finished.

${mergeFieldBlock()}

THE WORKFLOWS THAT NEED COPY. Each one already has a name, a trigger and a description of what the customer sees. Match your copy to that description — do not redesign the workflow, do not rename it, do not invent a step it does not have. Those descriptions use square-bracket shorthand like [Business] and [booking link] because they were written for a human reader; YOUR copy uses the real merge field in its place.

${workflowBlock(needed, true)}

RULES:
- Write the way the owner talks: short sentences, no marketing voice, no exclamation marks stacked up, no emoji. A customer should not be able to tell it was automated.
- ONE next step per message, and it is almost always the booking link.
- No invented discount, no invented deadline, no "last chance", no claim about how busy they are that nobody measured.
- Texts are short enough to read on a lock screen. Emails are complete but not long.
- The OWNER notification is internal — it goes to the owner's phone, never to the customer. Write it as facts he can act on in five seconds: who, what they want, why it scored urgent, and the number to tap.
- REVIEW REPLIES are posted in public under the review. The good one is specific and warm and never asks for anything. The middling one thanks them and asks what would have made it better. The bad one never argues, never mentions money or a refund, never restates the customer's complaint back at them, and offers to take it to a phone call. All three are signed as the business.
- The REACTIVATION campaign goes to people who have not heard from this business in a long time. Lead with who it is, why they are hearing from them, and a one-tap way to hear nothing further.
- The PAYMENT message is sent to somebody who has already said yes. It confirms what they are paying for and what happens once it clears. It never chases, never pressures, and never implies the slot is at risk unless holding the slot really does depend on the deposit.
- Never write a timing promise the automation does not keep.

Return JSON in EXACTLY this shape:
{
  "assets": [
    {
      "workflowId": "the exact id from the list above",
      "messages": [
        {"step": "which message this is, e.g. 'Step 1 · text, within a minute' or 'One or two stars'", "channel": "Text|Email|Owner notification|Public review reply|Direct message", "timing": "when it fires", "subject": "emails only — omit otherwise", "body": "the finished message", "mergeFields": ["{{contact.first_name}}"]}
      ]
    }
  ]
}

Provide one asset per workflow listed above, using its exact id, with the number of messages that workflow's "write:" line asks for. No other keys.`;

  const out = await generateJson<{ assets: WorkflowCopyAsset[] }>(prompt, undefined, { label: "workflowCopy" });
  return { assets: stampWorkflowCopy(needed, out.assets ?? []), coverage };
}

/**
 * Merge the model's messages onto the catalogue's workflows.
 *
 * Name, trigger and destination are STAMPED — a paraphrased workflow name is a
 * document that does not match the sub-account the operator has open, and a
 * guessed destination is a customer message pasted into an internal step.
 *
 * A workflow the model skipped is still emitted, with no messages. That is
 * deliberate: an empty slot is a gap the operator can see and regenerate, and a
 * dropped asset is one he finds out about from the client.
 *
 * Exported for fixture parity, like the other stampers.
 */
export function stampWorkflowCopy(
  needed: ResolvedWorkflow[],
  modelAssets: WorkflowCopyAsset[]
): WorkflowCopyAsset[] {
  const byId = new Map(modelAssets.map((a) => [a.workflowId, a]));
  return needed.map((r) => {
    const w = r.workflow;
    return {
      workflowId: w.id,
      workflowName: w.name,
      trigger: w.trigger,
      where: WORKFLOW_WHERE_OVERRIDE[w.id] ?? `${WORKFLOW_WHERE_PREFIX}${w.name}`,
      messages: (byId.get(w.id)?.messages ?? []).map((m) => ({
        ...m,
        // An email with no subject is a workflow step that cannot be saved.
        subject: m.channel?.toLowerCase() === "email" ? m.subject ?? "" : m.subject,
      })),
    };
  });
}

// ── Orchestration ────────────────────────────────────────────────────────────

// Operator-facing names for the five individually-regenerable sections. They say
// what the section IS now: file 3 and file 4 are the two halves of one 60-day
// workflow, not two independent sequences, and regenerating one without the other
// is how the two halves start repeating each other.
const SECTION_LABELS: Record<AssetSection, string> = {
  file1: "Growth Audit",
  file2: "Lead Qualification System",
  file3: "60-Day Nurture — Emails",
  file4: "60-Day Nurture — Texts",
  file5: "Booking & Appointment System",
};

export function sectionLabel(section: AssetSection): string {
  return SECTION_LABELS[section];
}

export async function generateOneSection(
  section: AssetSection,
  ctx: GenerationContext
): Promise<AssetPack[AssetSection]> {
  switch (section) {
    case "file1":
      return generateFile1(ctx);
    case "file2":
      return generateFile2(ctx);
    case "file3":
      return generateFile3(ctx);
    case "file4":
      return generateFile4(ctx);
    case "file5":
      return generateFile5(ctx);
  }
}

export function buildMeta(ctx: GenerationContext) {
  const i = ctx.intel;
  return {
    businessName: ctx.business.name,
    city: ctx.business.city ?? "",
    industry: ctx.business.industry ?? ctx.business.category ?? "local business",
    generatedAt: new Date().toISOString(),
    dataConfidence: i.dataConfidence,
    assumptions: i.assumptions,
    // No intake at all → mark the pack as an internal test on every cover.
    internalTest: ctx.intakePresent ? undefined : true,
    signals: {
      websiteScraped: i.website.hasWebsite,
      reviewsAnalyzed: i.reviews.available || Boolean(i.dataForSeo?.reviews.available),
      competitorsAnalyzed: i.competitors.available,
      performanceMeasured: Boolean(i.performance?.available),
      gbpProfilePulled: Boolean(i.dataForSeo?.gbp.available),
      screenshotsCaptured: Boolean(i.screenshots?.available),
      verifiedFactsExtracted: Boolean(
        i.verifiedFacts &&
          (i.verifiedFacts.phones.value.length ||
            i.verifiedFacts.services.value.length ||
            i.verifiedFacts.bookingLinks.value.length)
      ),
    },
  };
}

// Reports real generation progress: fires once per deliverable as it actually
// resolves, so the UI can show true completion instead of a guessed timer.
export type AssetProgressFn = (completed: number, total: number, label: string) => void;

// Number of parallel deliverable calls that make up a full pack. It drives the
// progress bar's denominator, so it has to match the Promise.all below exactly —
// leave it too high and generation appears to stall just short of finishing.
export const ASSET_PACK_PARTS = 11;

// All eleven calls fire in parallel. The token bucket in generateJson keeps us
// under the model's TPM ceiling if it's ever tight; on gpt-4o-mini there is ample
// headroom, so the pack completes in ~30s. When onProgress is provided, each call
// reports the moment it lands so the client tracks real progress.
export async function generateAssetPack(
  ctx: GenerationContext,
  onProgress?: AssetProgressFn
): Promise<AssetPack> {
  let completed = 0;
  const track = <T>(label: string, p: Promise<T>): Promise<T> =>
    p.then((r) => {
      completed += 1;
      onProgress?.(completed, ASSET_PACK_PARTS, label);
      return r;
    });

  const [
    file1,
    file2,
    file3,
    file4,
    file5,
    intelligence,
    infrastructure,
    supportingAssets,
    roadmap,
    surfaces,
    workflowCopy,
  ] = (await Promise.all([
    track("Growth audit", generateFile1(ctx)),
    track("Lead qualification system", generateFile2(ctx)),
    track("60-day nurture — emails", generateFile3(ctx)),
    track("60-day nurture — texts", generateFile4(ctx)),
    track("Booking & show-up system", generateFile5(ctx)),
    track("Growth leak intelligence", generateIntelligence(ctx)),
    track("Acquisition infrastructure", generateInfrastructure(ctx)),
    track("Review & thank-you assets", generateSupportingAssets(ctx)),
    track("Implementation timeline", generateRoadmap(ctx)),
    track("Booking page, form, webchat & site advice", generateConversionSurfaces(ctx)),
    track("Workflow copy", generateWorkflowCopy(ctx)),
  ])) as [
    GrowthAuditFile,
    LeadQualificationFile,
    EmailNurtureFile,
    SmsFollowUpFile,
    BookingSystemFile,
    GrowthIntelligence,
    AcquisitionInfrastructure,
    SupportingAssets,
    GrowthRoadmap,
    ConversionSurfaces,
    WorkflowCopyPack,
  ];

  // Defect 5: scrub any fabricated "$N off" / "N% off" promotion across EVERY
  // deliverable before the pack is returned — no invented offers ship.
  //
  // NOTE what is NOT here: `landing`. The landing-page module was the pack's 10th
  // call and it is gone. Saved packs still carry theirs and still render it; a new
  // pack carries `surfaces` instead.
  return sanitizeInventedOffers({
    meta: buildMeta(ctx),
    file1,
    file2,
    file3,
    file4,
    file5,
    intelligence,
    infrastructure,
    supportingAssets,
    roadmap,
    surfaces,
    workflowCopy,
  });
}
